@Test
public void testMockJniScanner() throws IOException {
    OffHeap.setTesting();
    MockJniScanner scanner = new MockJniScanner(32, new HashMap<String, String>() {

        {
            put("mock_rows", "128");
            put("required_fields", "boolean,tinyint,smallint,int,bigint,largeint,float,double," + "date,timestamp,char,varchar,string,decimalv2,decimal64,array,map,struct," + "decimal18,timestamp4,datev1,datev2,datetimev1,datetimev2");
            put("columns_types", "boolean#tinyint#smallint#int#bigint#largeint#float#double#" + "date#timestamp#char(10)#varchar(10)#string#decimalv2(12,4)#decimal64(10,3)#" + "array<array<string>>#map<string,array<int>>#struct<col1:timestamp(6),col2:array<char(10)>>#" + "decimal(18,5)#timestamp(4)#datev1#datev2#datetimev1#datetimev2(4)");
        }
    });
    scanner.open();
    long metaAddress = 0;
    do {
        metaAddress = scanner.getNextBatchMeta();
        if (metaAddress != 0) {
            long rows = OffHeap.getLong(null, metaAddress);
            Assert.assertEquals(32, rows);
            VectorTable restoreTable = VectorTable.createReadableTable(scanner.getTable().getColumnTypes(), scanner.getTable().getFields(), metaAddress);
            System.out.println(restoreTable.dump((int) rows).substring(0, 128));
            // Restored table is release by the origin table.
        }
        scanner.resetTable();
    } while (metaAddress != 0);
    scanner.releaseTable();
    scanner.close();
}

@Test
public void testVarint64IntEncode() throws IOException {
    long[] sourceValue = { 0, 1000, Integer.MAX_VALUE, Long.MAX_VALUE };
    for (long value : sourceValue) {
        ByteArrayOutputStream byteArrayOutput = new ByteArrayOutputStream();
        DataOutput output = new DataOutputStream(byteArrayOutput);
        Codec.encodeVarint64(value, output);
        Assert.assertEquals(value, Codec.decodeVarint64(new DataInputStream(new ByteArrayInputStream(byteArrayOutput.toByteArray()))));
    }
}

