    Assert.assertEquals(indexChangejob.invertedIndexBatchTask.getTaskNum(), 3);
    // run running job
    schemaChangeHandler.runAfterCatalogReady();
    Assert.assertEquals(IndexChangeJob.JobState.RUNNING, indexChangejob.getJobState());
