    ArrayLiteral arrayLiteral15 = new ArrayLiteral(structLiteral);
    Assert.assertEquals("[{\"col1\":1, \"col2\":2.15, \"col3\":\"2022-10-10\"}]", arrayLiteral15.getStringValueForStreamLoad(options));
}

