@Test
public void testNormal() throws UserException {
    SlotRef labelSlotRef = new SlotRef(null, "label");
    StringLiteral labelStringLiteral = new StringLiteral("doris_test_label");
    SlotRef stateSlotRef = new SlotRef(null, "state");
    BinaryPredicate labelBinaryPredicate = new BinaryPredicate(BinaryPredicate.Operator.EQ, labelSlotRef, labelStringLiteral);
    CancelExportStmt stmt = new CancelExportStmt(null, labelBinaryPredicate);
    stmt.analyze(analyzer);
    Assertions.assertEquals("CANCEL EXPORT FROM testDb WHERE (`label` = 'doris_test_label')", stmt.toString());
    SlotRef labelSlotRefUpper = new SlotRef(null, "LABEL");
    BinaryPredicate labelBinaryPredicateUpper = new BinaryPredicate(BinaryPredicate.Operator.EQ, labelSlotRefUpper, labelStringLiteral);
    CancelExportStmt stmtUpper = new CancelExportStmt(null, labelBinaryPredicateUpper);
    stmtUpper.analyze(analyzer);
    Assertions.assertEquals("CANCEL EXPORT FROM testDb WHERE (`LABEL` = 'doris_test_label')", stmtUpper.toString());
    StringLiteral stateStringLiteral = new StringLiteral("PENDING");
    BinaryPredicate stateBinaryPredicate = new BinaryPredicate(BinaryPredicate.Operator.EQ, stateSlotRef, stateStringLiteral);
    stmt = new CancelExportStmt(null, stateBinaryPredicate);
    stmt.analyze(analyzer);
    Assertions.assertEquals("CANCEL EXPORT FROM testDb WHERE (`state` = 'PENDING')", stmt.toString());
    LikePredicate labelLikePredicate = new LikePredicate(LikePredicate.Operator.LIKE, labelSlotRef, labelStringLiteral);
    stmt = new CancelExportStmt(null, labelLikePredicate);
    stmt.analyze(analyzer);
    Assertions.assertEquals("CANCEL EXPORT FROM testDb WHERE `label` LIKE 'doris_test_label'", stmt.toString());
    CompoundPredicate compoundAndPredicate = new CompoundPredicate(Operator.AND, labelBinaryPredicate, stateBinaryPredicate);
    stmt = new CancelExportStmt(null, compoundAndPredicate);
    stmt.analyze(analyzer);
    Assertions.assertEquals("CANCEL EXPORT FROM testDb WHERE ((`label` = 'doris_test_label') AND (`state` = 'PENDING'))", stmt.toString());
    CompoundPredicate compoundOrPredicate = new CompoundPredicate(Operator.OR, labelBinaryPredicate, stateBinaryPredicate);
    stmt = new CancelExportStmt(null, compoundOrPredicate);
    stmt.analyze(analyzer);
    Assertions.assertEquals("CANCEL EXPORT FROM testDb WHERE ((`label` = 'doris_test_label') OR (`state` = 'PENDING'))", stmt.toString());
}

