@Test
public void testIsNullable(@Injectable Expr caseExpr, @Injectable Expr whenExpr, @Injectable Expr thenExpr, @Injectable Expr elseExpr) {
    // without case without else
    CaseWhenClause caseWhenClause = new CaseWhenClause(whenExpr, thenExpr);
    List<CaseWhenClause> caseWhenClauseList = Lists.newArrayList();
    caseWhenClauseList.add(caseWhenClause);
    CaseExpr caseExpr1 = new CaseExpr(null, caseWhenClauseList, null);
    new Expectations() {

        {
            thenExpr.isNullable();
            result = false;
        }
    };
    Assert.assertTrue(caseExpr1.isNullable());
    // with case without else
    CaseExpr caseExpr2 = new CaseExpr(caseExpr, caseWhenClauseList, null);
    new Expectations() {

        {
            thenExpr.isNullable();
            result = false;
        }
    };
    Assert.assertTrue(caseExpr2.isNullable());
    // with case with else
    CaseExpr caseExpr3 = new CaseExpr(caseExpr, caseWhenClauseList, elseExpr);
    new Expectations() {

        {
            thenExpr.isNullable();
            result = false;
            elseExpr.isNullable();
            result = true;
        }
    };
    Assert.assertTrue(caseExpr3.isNullable());
}

@Test
public void testTypeCast(@Injectable Expr caseExpr, @Injectable Expr whenExpr, @Injectable Expr thenExpr, @Injectable Expr elseExpr) throws Exception {
    CaseWhenClause caseWhenClause = new CaseWhenClause(whenExpr, thenExpr);
    List<CaseWhenClause> caseWhenClauseList = Lists.newArrayList();
    caseWhenClauseList.add(caseWhenClause);
    CaseExpr expr = new CaseExpr(caseExpr, caseWhenClauseList, elseExpr);
    Class<?> clazz = Class.forName("org.apache.doris.catalog.ScalarType");
    Constructor<?> constructor = clazz.getDeclaredConstructor(PrimitiveType.class);
    constructor.setAccessible(true);
    ScalarType intType = (ScalarType) constructor.newInstance(PrimitiveType.INT);
    ScalarType tinyIntType = (ScalarType) constructor.newInstance(PrimitiveType.TINYINT);
    new Expectations() {

        {
            caseExpr.getType();
            result = intType;
            whenExpr.getType();
            result = ScalarType.createType(PrimitiveType.INT);
            whenExpr.castTo(intType);
            times = 0;
            thenExpr.getType();
            result = tinyIntType;
            thenExpr.castTo(tinyIntType);
            times = 0;
            elseExpr.getType();
            result = ScalarType.createType(PrimitiveType.TINYINT);
            elseExpr.castTo(tinyIntType);
            times = 0;
        }
    };
    Analyzer analyzer = new Analyzer(null, null);
    expr.analyzeImpl(analyzer);
}

@Test
public void testNormal() throws AnalysisException {
    ColumnDef column = new ColumnDef("col", intCol);
    column.analyze(true);
    Assert.assertEquals("`col` int NOT NULL COMMENT \"\"", column.toString());
    Assert.assertEquals("col", column.getName());
    Assert.assertEquals(PrimitiveType.INT, column.getType().getPrimitiveType());
    Assert.assertNull(column.getAggregateType());
    Assert.assertNull(column.getDefaultValue());
    // default
    column = new ColumnDef("col", intCol, true, null, false, new DefaultValue(true, "10"), "");
    column.analyze(true);
    Assert.assertNull(column.getAggregateType());
    Assert.assertEquals("10", column.getDefaultValue());
    Assert.assertEquals("`col` int NOT NULL DEFAULT \"10\" COMMENT \"\"", column.toSql());
    // agg
    column = new ColumnDef("col", floatCol, false, AggregateType.SUM, false, new DefaultValue(true, "10"), "");
    column.analyze(true);
    Assert.assertEquals("10", column.getDefaultValue());
    Assert.assertEquals(AggregateType.SUM, column.getAggregateType());
    Assert.assertEquals("`col` float SUM NOT NULL DEFAULT \"10\" COMMENT \"\"", column.toSql());
    // agg none
    column = new ColumnDef("col", bitmapCol, false, AggregateType.NONE, false, DefaultValue.BITMAP_EMPTY_DEFAULT_VALUE, "");
    Assert.assertEquals(AggregateType.NONE, column.getAggregateType());
    Assert.assertEquals("`col` bitmap NOT NULL DEFAULT BITMAP_EMPTY COMMENT \"\"", column.toSql());
}

