    String badExecuteSql = "CREATE JOB job1 ON SCHEDULE AT \"2023-02-15\" DO selects * from address ;";
    Assertions.assertThrows(AnalysisException.class, () -> {
        sqlParse(badExecuteSql);
    });
    String badSql = "CREATE JOB job1 ON SCHEDULE AT \"2023-02-15\" STARTS \"2023-02-15\" DO selects * from address ;";
    Assertions.assertThrows(AnalysisException.class, () -> {
        sqlParse(badSql);
    });
}

@Test
public void createCycleJob() throws Exception {
    String sql = "CREATE JOB job1 ON SCHEDULE EVERY  1 SECOND STARTS \"2023-02-15\" DO SELECT * FROM `address` ;";
    CreateJobStmt jobStmt = sqlParse(sql);
    Assertions.assertEquals("SELECT * FROM `address`", jobStmt.getDoStmt().toSql());
    sql = "CREATE JOB job1 ON SCHEDULE EVERY  1 SECOND ENDS \"2023-02-15\" DO SELECT * FROM `address` ;";
    jobStmt = sqlParse(sql);
    Assertions.assertEquals("SELECT * FROM `address`", jobStmt.getDoStmt().toSql());
    sql = "CREATE JOB job1 ON SCHEDULE EVERY  1 SECOND STARTS \"2023-02-15\" ENDS \"2023-02-16\" DO SELECT * FROM `address` ;";
    jobStmt = sqlParse(sql);
    Assertions.assertEquals("SELECT * FROM `address`", jobStmt.getDoStmt().toSql());
    sql = "CREATE JOB job1 ON SCHEDULE EVERY  1 SECOND  DO SELECT * FROM `address` ;";
    jobStmt = sqlParse(sql);
    Assertions.assertEquals("SELECT * FROM `address`", jobStmt.getDoStmt().toSql());
    String badExecuteSql = "CREATE JOB job1 ON SCHEDULE AT \"2023-02-15\" DO selects * from address ;";
    Assertions.assertThrows(AnalysisException.class, () -> {
        sqlParse(badExecuteSql);
    });
    String badSql = "CREATE JOB job1 ON SCHEDULE AT \"2023-02-15\" STARTS \"2023-02-15\" DO selects * from address ;";
    Assertions.assertThrows(AnalysisException.class, () -> {
        sqlParse(badSql);
    });
}

@Test
public void testParseExecuteSql() throws NoSuchMethodException, InvocationTargetException, IllegalAccessException {
    Method method = CreateJobStmt.class.getDeclaredMethod("parseExecuteSql", String.class, String.class, String.class);
    method.setAccessible(true);
    String executeSql = "insert into table.B select * from table.A ;";
    String comment = "do do do do ";
    String jobName = "do";
    String doKeywordJobSql = "Create job " + jobName + "on Scheduler every second comment " + comment + "\n" + "do" + executeSql;
    String result = (String) method.invoke(null, doKeywordJobSql, jobName, comment);
    Assertions.assertEquals(executeSql, result.trim());
    executeSql = "insert into table.do select * from do.B ;";
    comment = "do starts  end do \n \b \r ";
    jobName = "do";
    doKeywordJobSql = "Create job " + jobName + "on Scheduler every second comment " + comment + "do\n" + executeSql;
    result = (String) method.invoke(null, doKeywordJobSql, jobName, comment);
    Assertions.assertEquals(executeSql, result.trim());
}

