@Test
public void testPersist() throws IOException {
    MetaContext metaContext = new MetaContext();
    metaContext.setMetaVersion(FeMetaVersion.VERSION_CURRENT);
    metaContext.setThreadLocalInfo();
    // 1. Write objects to file
    File file = new File("./expr_test");
    boolean success = file.createNewFile();
    if (!success) {
        Assertions.fail("create file expr_test failed.");
    }
    DataOutputStream dos = new DataOutputStream(Files.newOutputStream(file.toPath()));
    // cos(1) + (100 / 200)
    Expr child1 = new IntLiteral(1);
    Expr functionCall = new FunctionCallExpr("cos", Lists.newArrayList(child1));
    Expr child21 = new IntLiteral(100);
    Expr child22 = new IntLiteral(200);
    Expr arithExpr1 = new ArithmeticExpr(ArithmeticExpr.Operator.DIVIDE, child21, child22);
    Expr arithExpr2 = new ArithmeticExpr(ArithmeticExpr.Operator.ADD, functionCall, arithExpr1);
    Expr.writeTo(arithExpr2, dos);
    dos.flush();
    dos.close();
    // 2. Read objects from file
    DataInputStream dis = new DataInputStream(Files.newInputStream(file.toPath()));
    Expr readExpr = Expr.readIn(dis);
    Assertions.assertInstanceOf(ArithmeticExpr.class, readExpr);
    Assertions.assertEquals("(cos(1) + (100 / 200))", readExpr.toSql());
    // 3. delete files
    dis.close();
    file.delete();
}

@Test
public void testGetTableNameToColumnNames(@Mocked Analyzer analyzer, @Injectable SlotDescriptor slotDesc1, @Injectable SlotDescriptor slotDesc2, @Injectable TupleDescriptor tupleDescriptor1, @Injectable TupleDescriptor tupleDescriptor2, @Injectable Table tableA, @Injectable Table tableB) throws AnalysisException {
    TableName tableAName = new TableName(internalCtl, "test", "tableA");
    TableName tableBName = new TableName(internalCtl, "test", "tableB");
    SlotRef tableAColumn1 = new SlotRef(tableAName, "c1");
    SlotRef tableBColumn1 = new SlotRef(tableBName, "c1");
    Expr whereExpr = new BinaryPredicate(BinaryPredicate.Operator.EQ, tableAColumn1, tableBColumn1);
    Deencapsulation.setField(tableAColumn1, "desc", slotDesc1);
    Deencapsulation.setField(tableBColumn1, "desc", slotDesc2);
    new Expectations() {

        {
            slotDesc1.getColumn().getName();
            result = "c1";
            slotDesc2.getColumn().getName();
            result = "c1";
            slotDesc1.getParent();
            result = tupleDescriptor1;
            slotDesc2.getParent();
            result = tupleDescriptor2;
            tupleDescriptor1.getTable();
            result = tableA;
            tupleDescriptor2.getTable();
            result = tableB;
            tableA.getId();
            result = 1;
            tableB.getId();
            result = 2;
        }
    };
