@Test
public void testCollectExprs() throws Exception {
    ConnectContext ctx = UtFrameUtils.createDefaultCtx();
    Analyzer analyzer = new Analyzer(ctx.getEnv(), ctx);
    String sql = "SELECT CASE
" + "        WHEN (
" + "            SELECT COUNT(*) / 2
" + "            FROM db1.tbl1
" + "        ) > k4 THEN (
" + "            SELECT AVG(k4)
" + "            FROM db1.tbl1
" + "        )
" + "        ELSE (
" + "            SELECT SUM(k4)
" + "            FROM db1.tbl1
" + "        )
" + "    END AS kk4
" + "FROM db1.tbl1;";
    QueryStmt stmt = (QueryStmt) UtFrameUtils.parseAndAnalyzeStmt(sql, ctx);
    Map<String, Expr> exprsMap = new HashMap<>();
    stmt.collectExprs(exprsMap);
    Assert.assertEquals(4, exprsMap.size());
    Map<String, TExpr> constMap = getConstantExprMap(exprsMap, analyzer);
    Assert.assertEquals(0, constMap.size());
    sql = "SELECT username
" + "FROM db1.table1
" + "WHERE siteid in
" + "    (SELECT abs(5+abs(0))+1)
" + "UNION
" + "SELECT CASE
" + "           WHEN
" + "                  (SELECT count(*)+abs(8)
" + "                   FROM db1.table1
" + "                   WHERE username='helen')>1 THEN 888
" + "           ELSE 999
" + "       END AS ccc
" + "FROM
" + "  (SELECT curdate()) a " + "ORDER BY curdate();";
    stmt = (QueryStmt) UtFrameUtils.parseAndAnalyzeStmt(sql, ctx);
    exprsMap.clear();
    stmt.collectExprs(exprsMap);
    Assert.assertEquals(8, exprsMap.size());
    constMap.clear();
    constMap = getConstantExprMap(exprsMap, analyzer);
    Assert.assertEquals(4, constMap.size());
    sql = "select
" + "   avg(t1.k4)
" + "from
" + "   db1.tbl1 t1,
" + "   db1.tbl1 t2,
" + "   db1.tbl1 t3,
" + "   db1.tbl1 t4,
" + "   db1.tbl1 t5,
" + "   db1.tbl1 t6
" + "where
" + "   t2.k1 = t1.k1
" + "   and t1.k2 = t6.k2
" + "   and t6.k4 = 2001
" + "   and(
" + "      (
" + "         t1.k2 = t4.k2
" + "         and t3.k3 = t1.k3
" + "         and t3.k1 = 'D'
" + "         and t4.k3 = '2 yr Degree'
" + "         and t1.k4 between 100.00
" + "         and 150.00
" + "         and t4.k4 = 3
" + "      )
" + "      or (
" + "         t1.k2 = t4.k2
" + "         and t3.k3 = t1.k3
" + "         and t3.k1 = 'S'
" + "         and t4.k3 = 'Secondary'
" + "         and t1.k4 between 50.00
" + "         and 100.00
" + "         and t4.k4 = 1
" + "      )
" + "      or (
" + "         t1.k2 = t4.k2
" + "         and t3.k3 = t1.k3
" + "         and t3.k1 = 'W'
" + "         and t4.k3 = 'Advanced Degree'
" + "         and t1.k4 between 150.00
" + "         and 200.00
" + "         and t4.k4  = 1
" + "      )
" + "   )
" + "   and(
" + "      (
" + "         t1.k1 = t5.k1
" + "         and t5.k2 = 'United States'
" + "         and t5.k3  in ('CO', 'IL', 'MN')
" + "         and t1.k4 between 100
" + "         and 200
" + "      )
" + "      or (
" + "         t1.k1 = t5.k1
" + "         and t5.k2 = 'United States'
" + "         and t5.k3 in ('OH', 'MT', 'NM')
" + "         and t1.k4 between 150
" + "         and 300
" + "      )
" + "      or (
" + "         t1.k1 = t5.k1
" + "         and t5.k2 = 'United States'
" + "         and t5.k3 in ('TX', 'MO', 'MI')
" + "         and t1.k4 between 50 and 250
" + "      )
" + "   );";
    stmt = (QueryStmt) UtFrameUtils.parseAndAnalyzeStmt(sql, ctx);
    exprsMap.clear();
    stmt.collectExprs(exprsMap);
    Assert.assertEquals(2, exprsMap.size());
    constMap.clear();
    constMap = getConstantExprMap(exprsMap, analyzer);
    Assert.assertEquals(0, constMap.size());
    sql = "SELECT k1 FROM db1.baseall GROUP BY k1 HAVING EXISTS(SELECT k4 FROM db1.tbl1 GROUP BY k4 " + "HAVING SUM(k4) = k4);";
    stmt = (QueryStmt) UtFrameUtils.parseAndAnalyzeStmt(sql, ctx);
    exprsMap.clear();
    stmt.collectExprs(exprsMap);
    Assert.assertEquals(4, exprsMap.size());
    constMap.clear();
    constMap = getConstantExprMap(exprsMap, analyzer);
    Assert.assertEquals(0, constMap.size());
    // inline view
    sql = "select a.k1, b.now from (select k1,k2 from db1.baseall)a, (select now() as now)b";
    stmt = (QueryStmt) UtFrameUtils.parseAndAnalyzeStmt(sql, ctx);
    exprsMap.clear();
    stmt.collectExprs(exprsMap);
    Assert.assertEquals(5, exprsMap.size());
    constMap.clear();
    constMap = getConstantExprMap(exprsMap, analyzer);
    Assert.assertEquals(2, constMap.size());
    // expr in subquery associate with column in grandparent level
    sql = "WITH aa AS
" + "        (SELECT DATE_FORMAT(workDateTime, '%Y-%m') mon,
" + "                DATE_FORMAT(workDateTimeV2, '%Y-%m') mon1,
" + "                siteid
" + "                FROM db1.table1
" + "                WHERE workDateTime >= concat(year(now())-1, '-01-01 00:00:00')
" + "                AND workDateTimeV2 >= concat(year(now())-1, '-01-01 00:00:00')
" + "                AND workDateTimeV2 >= concat(year(now())-1, '-01-01 00:00:00.000000')
" + "                AND workDateTime < now()
" + "                AND workDateTimeV2 < now()
" + "                GROUP BY siteid,
" + "                DATE_FORMAT(workDateTime, '%Y-%m'),
" + "                DATE_FORMAT(workDateTimeV2, '%Y-%m')),
" + "        bb AS
" + "        (SELECT mon,
" + "                count(DISTINCT siteid) total
" + "                FROM aa
" + "                GROUP BY mon),
" + "        cc AS
" + "        (SELECT mon,
" + "                 count(DISTINCT siteid) num
" + "                FROM aa
" + "                GROUP BY mon)
" + "SELECT bb.mon,
" + "        round(cc.num / bb.total, 4) rate
" + "FROM bb
" + "LEFT JOIN cc ON cc.mon = bb.mon
" + "ORDER BY mon;";
    // When disable vec engine, this sql can be analyzed successfully.
    // But when enable vec engine and for now, it will throw VecNotImplException
    // with msg: "could not be changed to nullable".
    // So here we make a "if else" check, and once this VecNotImplException is fixed, we should remove this check.
}

