    String sql = "SELECT username, @@license, @@time_zone
" + "FROM db1.table1
" + "WHERE siteid in
" + "    (SELECT abs(5+abs(0))+1)
" + "UNION
" + "SELECT CASE
" + "           WHEN
" + "                  (SELECT count(*)+abs(8)
" + "                   FROM db1.table1
" + "                   WHERE username='helen')>1 THEN 888
" + "           ELSE 999
" + "       END AS ccc, @@language, @@storage_engine
" + "FROM
" + "  (SELECT curdate()) a;";
    StatementBase stmt = UtFrameUtils.parseAndAnalyzeStmt(sql, ctx);
    SessionVariable sessionVariable = new SessionVariable();
    TQueryOptions queryOptions = sessionVariable.toThrift();
    stmt.foldConstant(new Analyzer(ctx.getEnv(), ctx).getExprRewriter(), queryOptions);
    // reAnalyze
    reAnalyze(stmt, ctx);
    Assert.assertTrue(stmt.toSql().contains("Apache License, Version 2.0"));
    Assert.assertTrue(stmt.toSql().contains("/palo/share/english/"));
    // test sysVariableDescs
    sql = "SELECT
" + "   avg(t1.k4)
" + "FROM
" + "   db1.tbl1 t1,
" + "   db1.tbl1 t2
" + "WHERE
" + "(
" + "   t2.k2 = 'United States'
" + "   AND t2.k3  in (@@license, @@version)
" + ")
" + "OR (
" + "   t2.k2 = @@language
" + ")";
    stmt = UtFrameUtils.parseAndAnalyzeStmt(sql, ctx);
    stmt.foldConstant(new Analyzer(ctx.getEnv(), ctx).getExprRewriter(), queryOptions);
    // reAnalyze
    reAnalyze(stmt, ctx);
    Assert.assertTrue(stmt.toSql().contains("Apache License, Version 2.0"));
    Assert.assertTrue(stmt.toSql().contains("/palo/share/english/"));
    // test informationFunctions
    sql = "SELECT
" + "   avg(t1.k4)
" + "FROM
" + "   db1.tbl1 t1,
" + "   db1.tbl1 t2
" + "WHERE
" + "(
" + "   t2.k2 = 'United States'
" + "   AND t2.k1  in (USER(), CURRENT_USER(), SCHEMA())
" + ")
" + "OR (
" + "   t2.k2 = CONNECTION_ID()
" + ")";
    stmt = UtFrameUtils.parseAndAnalyzeStmt(sql, ctx);
    stmt.foldConstant(new Analyzer(ctx.getEnv(), ctx).getExprRewriter(), queryOptions);
    // reAnalyze
    reAnalyze(stmt, ctx);
    Assert.assertTrue(stmt.toSql().contains("root''@''%"));
    Assert.assertTrue(stmt.toSql().contains("root''@''127.0.0.1"));
    // inline view
    sql = "SELECT
" + "   t1.k1, t2.k1
" + "FROM
" + "   (select USER() k1, CURRENT_USER() k2, SCHEMA() k3) t1,
" + "   (select @@license k1, @@version k2) t2
";
