        ShowBackupStmt stmt = new ShowBackupStmt("test", new BoolLiteral(true));
        Assertions.assertThrows(AnalysisException.class, () -> stmt.analyze(analyzer));
    }
    /* where clause op not supported */
    {
        ShowBackupStmt stmt = new ShowBackupStmt("test", new LikePredicate(Operator.REGEXP, new SlotRef(new TableName(), "STATE_NAME"), new StringLiteral("%.b.%")));
        Assertions.assertThrows(AnalysisException.class, () -> stmt.analyze(analyzer));
    }
    /* where clause op not supported*/
    {
        ShowBackupStmt stmt = new ShowBackupStmt("test", new BinaryPredicate(BinaryPredicate.Operator.GE, new SlotRef(new TableName(), "STATE_NAME"), new StringLiteral("blah")));
        Assertions.assertThrows(AnalysisException.class, () -> stmt.analyze(analyzer));
    }
    /*where clause op not supported*/
    {
        ShowBackupStmt stmt = new ShowBackupStmt("test", new BinaryPredicate(BinaryPredicate.Operator.EQ, new SlotRef(new TableName(), "STATE_NAME"), new StringLiteral("blah")));
        Assertions.assertThrows(AnalysisException.class, () -> stmt.analyze(analyzer));
    }
    /* where clause op type(left) not supported */
    {
        ShowBackupStmt stmt = new ShowBackupStmt("test", new BinaryPredicate(BinaryPredicate.Operator.EQ, new IntLiteral(1), new IntLiteral(1)));
        Assertions.assertThrows(AnalysisException.class, () -> stmt.analyze(analyzer));
    }
    /* where clause op type(right) not supported */
