    }
    /* where clause operand is empty */
    {
        ShowBackupStmt stmt = new ShowBackupStmt("test", new BinaryPredicate(BinaryPredicate.Operator.EQ, new SlotRef(new TableName(), "snapshotname"), new StringLiteral("")));
        Assertions.assertThrows(AnalysisException.class, () -> stmt.analyze(analyzer));
    }
}

