@Test
public void testAlterView() throws Exception {
    String originStmt = "select k1 as kc1, sum(k2) as kc2 from test.tbl1 group by kc1";
    ExceptionChecker.expectThrowsNoException(() -> createView("create view test.alter1 as " + originStmt));
    Database db = Env.getCurrentInternalCatalog().getDbOrDdlException("test");
    View alter1 = (View) db.getTableOrDdlException("alter1");
    Assert.assertEquals("SELECT `k1` AS `kc1`, sum(`k2`) AS `kc2` FROM `test`.`tbl1` GROUP BY `kc1`", alter1.getInlineViewDef());
    String alterStmt = "alter view test.alter1 as with test1_cte (w1, w2) as (select k1, k2 from test.tbl1) " + "select w1 as c1, sum(w2) as c2 from test1_cte where w1 > 10 group by w1 order by w1";
    AlterViewStmt alterViewStmt = (AlterViewStmt) UtFrameUtils.parseAndAnalyzeStmt(alterStmt, connectContext);
    Env.getCurrentEnv().alterView(alterViewStmt);
    alter1 = (View) db.getTableOrDdlException("alter1");
    Assert.assertEquals("WITH test1_cte(w1, w2) AS (SELECT `k1`, `k2` FROM `test`.`tbl1`) " + "SELECT `w1` AS `c1`, sum(`w2`) AS `c2` FROM `test1_cte` WHERE (`w1` > 10) GROUP BY `w1` " + "ORDER BY `w1` ASC NULLS FIRST", alter1.getInlineViewDef());
}

@Test
public void lockTest() {
    db.readLock();
    try {
        Assert.assertFalse(db.tryWriteLock(0, TimeUnit.SECONDS));
    } finally {
        db.readUnlock();
    }
    db.writeLock();
    try {
        Assert.assertTrue(db.tryWriteLock(1000, TimeUnit.SECONDS));
        db.writeUnlock();
    } finally {
        db.writeUnlock();
    }
    db.markDropped();
    Assert.assertFalse(db.writeLockIfExist());
    Assert.assertFalse(db.isWriteLockHeldByCurrentThread());
    db.unmarkDropped();
    Assert.assertTrue(db.writeLockIfExist());
    Assert.assertTrue(db.isWriteLockHeldByCurrentThread());
    db.writeUnlock();
}

