@Test
public void testCreateDynamicPartitionImmediately() throws Exception {
    String createOlapTblStmt = "CREATE TABLE test.`empty_dynamic_partition` (\n" + "  `k1` date NULL COMMENT \"\",\n" + "  `k2` int NULL COMMENT \"\",\n" + "  `k3` smallint NULL COMMENT \"\",\n" + "  `v1` varchar(2048) NULL COMMENT \"\",\n" + "  `v2` datetime NULL COMMENT \"\"\n" + ") ENGINE=OLAP\n" + "DUPLICATE KEY(`k1`, `k2`, `k3`)\n" + "COMMENT \"OLAP\"\n" + "PARTITION BY RANGE(`k1`)\n" + "()\n" + "DISTRIBUTED BY HASH(`k1`) BUCKETS 32\n" + "PROPERTIES (\n" + "\"replication_num\" = \"1\",\n" + "\"dynamic_partition.enable\" = \"true\",\n" + "\"dynamic_partition.start\" = \"-3\",\n" + "\"dynamic_partition.end\" = \"3\",\n" + "\"dynamic_partition.time_unit\" = \"day\",\n" + "\"dynamic_partition.prefix\" = \"p\",\n" + "\"dynamic_partition.buckets\" = \"1\"\n" + ");";
    createTable(createOlapTblStmt);
    OlapTable emptyDynamicTable = (OlapTable) Env.getCurrentInternalCatalog().getDbOrAnalysisException("test").getTableOrAnalysisException("empty_dynamic_partition");
    Assert.assertTrue(emptyDynamicTable.getAllPartitions().size() == 4);
    Iterator<Partition> partitionIterator = emptyDynamicTable.getAllPartitions().iterator();
    List<String> partNames = Lists.newArrayList();
    while (partitionIterator.hasNext()) {
        String partitionName = partitionIterator.next().getName();
        partNames.add(partitionName.substring(1));
    }
    Collections.sort(partNames);
    int partitionCount = 0;
    DateTimeFormatter sdf = DateTimeFormatter.ofPattern("yyyyMMdd").withZone(ZoneId.systemDefault());
    for (String partName : partNames) {
        Date partitionDate = Date.from(LocalDate.parse(partName, sdf).atStartOfDay().atZone(ZoneId.systemDefault()).toInstant());
        Date date = new Date();
        Calendar calendar = new GregorianCalendar();
        calendar.setTime(date);
        calendar.add(calendar.DATE, partitionCount);
        date = calendar.getTime();
        Assert.assertEquals(partitionDate.getYear(), date.getYear());
        Assert.assertEquals(partitionDate.getMonth(), date.getMonth());
        Assert.assertEquals(partitionDate.getDay(), date.getDay());
        partitionCount++;
    }
}

