@Test
public void testTabletOnBadDisks() throws Exception {
    createDatabase("db1");
    createTable("create table db1.tbl1(k1 int) distributed by hash(k1) buckets 1" + " properties('replication_num' = '3')");
    Database db = Env.getCurrentInternalCatalog().getDbOrMetaException("db1");
    OlapTable tbl = (OlapTable) db.getTableOrMetaException("tbl1");
    Assertions.assertNotNull(tbl);
    Tablet tablet = tbl.getPartitions().iterator().next().getMaterializedIndices(MaterializedIndex.IndexExtState.ALL).iterator().next().getTablets().iterator().next();
    List<Replica> replicas = tablet.getReplicas();
    Assertions.assertEquals(3, replicas.size());
    for (Replica replica : replicas) {
        Assertions.assertTrue(replica.getPathHash() != -1L);
    }
    Assertions.assertEquals(replicas, tablet.getQueryableReplicas(1L, getAlivePathHashs(), false));
    // disk mark as bad
    Env.getCurrentSystemInfo().getBackend(replicas.get(0).getBackendId()).getDisks().values().forEach(disk -> disk.setState(DiskInfo.DiskState.OFFLINE));
    // lost disk
    replicas.get(1).setPathHash(-123321L);
    Assertions.assertEquals(Lists.newArrayList(replicas.get(2)), tablet.getQueryableReplicas(1L, getAlivePathHashs(), false));
}

