    List<Long> backendIds = Env.getCurrentSystemInfo().getAllBackendsByAllCluster().values().stream().map(Backend::getId).collect(Collectors.toList());
    List<Long> replicasBeIds = tablet.getReplicas().stream().map(Replica::getBackendIdWithoutException).collect(Collectors.toList());
    Assertions.assertEquals(2, replicasBeIds.size());
    Assertions.assertTrue(tabletSchedCtx.filterDestBE(replicasBeIds.get(0)));
    Assertions.assertTrue(tabletSchedCtx.filterDestBE(replicasBeIds.get(1)));
    List<Long> notInReplicaBeIds = backendIds.stream().filter(beId -> !replicasBeIds.contains(beId)).collect(Collectors.toList());
