@Test
public void test() {
    ThreadPoolExecutor executor = ThreadPoolManager.newDaemonFixedThreadPool(10, 10, "TestThreadPool", 120, true);
    LoadingCache<String, String> testCache = Caffeine.newBuilder().maximumSize(100).expireAfterAccess(1, TimeUnit.MINUTES).build(new CacheBulkLoader<String, String>() {

        @Override
        protected ExecutorService getExecutor() {
            return executor;
        }

        @Override
        public String load(String key) {
            Assertions.assertTrue(Thread.currentThread().getName().startsWith("TestThreadPool"));
            try {
                Thread.sleep(100);
            } catch (InterruptedException interruptedException) {
                interruptedException.printStackTrace();
            }
            return key.replace("k", "v");
        }
    });
    List<String> testKeys = IntStream.range(1, 101).boxed().map(i -> String.format("k%d", i)).collect(Collectors.toList());
    Map<String, String> vMap = testCache.getAll(testKeys);
    Assertions.assertTrue(MapUtils.isNotEmpty(vMap) && vMap.size() == testKeys.size());
    for (String key : vMap.keySet()) {
        Assertions.assertTrue(key.replace("k", "v").equals(vMap.get(key)));
    }
    try {
        executor.shutdown();
        executor.awaitTermination(10, TimeUnit.SECONDS);
    } catch (Exception e) {
        e.printStackTrace();
    }
}

@Test
public void testLoadingCacheWithoutExpireAfterWrite() throws InterruptedException {
    FakeTicker ticker = new FakeTicker();
    AtomicLong counter = new AtomicLong(0);
    CacheFactory cacheFactory = new CacheFactory(OptionalLong.empty(), OptionalLong.of(10), 1000, false, ticker::read);
    LoadingCache<Integer, CacheValue> loadingCache = cacheFactory.buildCache(key -> CacheValue.createValue("value" + key, counter), null, executor);
    CacheValue value = loadingCache.get(1);
    Assertions.assertEquals("value1", value.getValue());
    Assertions.assertEquals(1, counter.get());
    value = loadingCache.get(1);
    Assertions.assertEquals("value1", value.getValue());
    Assertions.assertEquals(1, counter.get());
    // advance 11 seconds to pass the refreshAfterWrite
    ticker.advance(11, TimeUnit.SECONDS);
