    // refresh in background, so still get value1
    Assertions.assertEquals("value1", value.getValue());
    // sleep longer to wait for refresh
    Thread.sleep(2500);
    value = loadingCache.get(1);
    Assertions.assertEquals("value1", value.getValue());
    Assertions.assertEquals(2, counter.get());
}

