@Test
public void testPutOnNonEmptyCacheImplementation() {
    Cache<Object, Object> cache = EvictableCacheBuilder.newBuilder().maximumSize(10).build();
    Map<Object, Object> cacheMap = cache.asMap();
    int key = 0;
    int value = 1;
    Exception putException = Assert.assertThrows("put operation should throw UnsupportedOperationException", UnsupportedOperationException.class, () -> cacheMap.put(key, value));
    Assert.assertEquals("The operation is not supported, as in inherently races with cache invalidation. Use get(key, callable) instead.", putException.getMessage());
