@Test
public void testCOSLocationConvert() {
    Map<String, String> rangeProps = new HashMap<>();
    LocationPath locationPath = new LocationPath("cos://test.com", rangeProps);
    // FE
    Assertions.assertTrue(locationPath.get().startsWith("cos://"));
