    beLocation = locationPath.toStorageLocation().toString();
    Assertions.assertTrue(beLocation.startsWith("gfs://"));
    Assertions.assertEquals(LocationPath.getFSIdentity(beLocation, Collections.emptyMap(), null).first, FileSystemType.DFS);
}

