@Test
public void testReplayMetaIdMappingsLog() {
    ExternalMetaIdMgr mgr = new ExternalMetaIdMgr();
    MetaIdMappingsLog log1 = new MetaIdMappingsLog();
    log1.setCatalogId(1L);
    log1.setFromHmsEvent(false);
    log1.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_ADD, MetaIdMappingsLog.META_OBJECT_TYPE_DATABASE, "db1", ExternalMetaIdMgr.nextMetaId()));
    mgr.replayMetaIdMappingsLog(log1);
    Assertions.assertNotEquals(-1L, mgr.getDbId(1L, "db1"));
    MetaIdMappingsLog log2 = new MetaIdMappingsLog();
    log2.setCatalogId(1L);
    log2.setFromHmsEvent(false);
    log2.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_DELETE, MetaIdMappingsLog.META_OBJECT_TYPE_DATABASE, "db1"));
    mgr.replayMetaIdMappingsLog(log2);
    Assertions.assertEquals(-1L, mgr.getDbId(1L, "db1"));
    MetaIdMappingsLog log3 = new MetaIdMappingsLog();
    log3.setCatalogId(1L);
    log3.setFromHmsEvent(false);
    log3.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_ADD, MetaIdMappingsLog.META_OBJECT_TYPE_TABLE, "db1", "tbl1", ExternalMetaIdMgr.nextMetaId()));
    mgr.replayMetaIdMappingsLog(log3);
    Assertions.assertEquals(-1L, mgr.getDbId(1L, "db1"));
    Assertions.assertNotEquals(-1L, mgr.getTblId(1L, "db1", "tbl1"));
    MetaIdMappingsLog log4 = new MetaIdMappingsLog();
    log4.setCatalogId(1L);
    log4.setFromHmsEvent(false);
    log4.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_DELETE, MetaIdMappingsLog.META_OBJECT_TYPE_TABLE, "db1", "tbl1"));
    log4.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_ADD, MetaIdMappingsLog.META_OBJECT_TYPE_PARTITION, "db1", "tbl1", "p1", ExternalMetaIdMgr.nextMetaId()));
    mgr.replayMetaIdMappingsLog(log4);
    Assertions.assertEquals(-1L, mgr.getDbId(1L, "db1"));
    Assertions.assertEquals(-1L, mgr.getTblId(1L, "db1", "tbl1"));
    Assertions.assertNotEquals(-1L, mgr.getPartitionId(1L, "db1", "tbl1", "p1"));
}

@Test
public void testLoadWithException() throws Exception {
    ThreadPoolExecutor executor = ThreadPoolManager.newDaemonFixedThreadPool(1, Integer.MAX_VALUE, "TEST", true);
    AtomicInteger counter = new AtomicInteger(0);
    new MockUp<ExternalRowCountCache.RowCountCacheLoader>() {

        @Mock
        protected Optional<Long> doLoad(ExternalRowCountCache.RowCountKey rowCountKey) {
            counter.incrementAndGet();
            return null;
        }
    };
    ExternalRowCountCache cache = new ExternalRowCountCache(executor);
    long cachedRowCount = cache.getCachedRowCount(1, 1, 1);
    Assertions.assertEquals(TableIf.UNKNOWN_ROW_COUNT, cachedRowCount);
    for (int i = 0; i < 60; i++) {
        if (counter.get() == 1) {
            break;
        }
        Thread.sleep(1000);
    }
    Assertions.assertEquals(1, counter.get());
    new MockUp<ExternalRowCountCache.RowCountCacheLoader>() {

        @Mock
        protected Optional<Long> doLoad(ExternalRowCountCache.RowCountKey rowCountKey) {
            counter.incrementAndGet();
            return Optional.of(100L);
        }
    };
    cache.getCachedRowCount(1, 1, 1);
    for (int i = 0; i < 60; i++) {
        cachedRowCount = cache.getCachedRowCount(1, 1, 1);
        if (cachedRowCount != TableIf.UNKNOWN_ROW_COUNT) {
            Assertions.assertEquals(100, cachedRowCount);
            break;
        }
        Thread.sleep(1000);
    }
    cachedRowCount = cache.getCachedRowCount(1, 1, 1);
    Assertions.assertEquals(100, cachedRowCount);
    Assertions.assertEquals(2, counter.get());
    new MockUp<ExternalRowCountCache.RowCountCacheLoader>() {

        @Mock
        protected Optional<Long> doLoad(ExternalRowCountCache.RowCountKey rowCountKey) {
            counter.incrementAndGet();
            try {
                Thread.sleep(1000000);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
            return Optional.of(100L);
        }
    };
    cachedRowCount = cache.getCachedRowCount(2, 2, 2);
    Assertions.assertEquals(TableIf.UNKNOWN_ROW_COUNT, cachedRowCount);
    Thread.sleep(1000);
    cachedRowCount = cache.getCachedRowCount(2, 2, 2);
    Assertions.assertEquals(TableIf.UNKNOWN_ROW_COUNT, cachedRowCount);
    for (int i = 0; i < 60; i++) {
        if (counter.get() == 3) {
            break;
        }
        Thread.sleep(1000);
    }
    Assertions.assertEquals(3, counter.get());
}

