@Test
public void testGetMatchingManifest() {
    // partition : 100 - 200
    GenericManifestFile f1 = getGenericManifestFileForDataTypeWithPartitionSummary("manifest_f1.avro", Collections.singletonList(new GenericPartitionFieldSummary(false, false, getByteBufferForLong(100), getByteBufferForLong(200))));
    // partition : 300 - 400
    GenericManifestFile f2 = getGenericManifestFileForDataTypeWithPartitionSummary("manifest_f2.avro", Collections.singletonList(new GenericPartitionFieldSummary(false, false, getByteBufferForLong(300), getByteBufferForLong(400))));
    // partition : 500 - 600
    GenericManifestFile f3 = getGenericManifestFileForDataTypeWithPartitionSummary("manifest_f3.avro", Collections.singletonList(new GenericPartitionFieldSummary(false, false, getByteBufferForLong(500), getByteBufferForLong(600))));
    List<ManifestFile> manifestFiles = new ArrayList<ManifestFile>() {

        {
            add(f1);
            add(f2);
            add(f3);
        }
    };
    Schema schema = new Schema(StructType.of(Types.NestedField.required(1, "id", LongType.get()), Types.NestedField.required(2, "data", LongType.get()), Types.NestedField.required(3, "par", LongType.get())).fields());
    // test empty partition spec
    HashMap<Integer, PartitionSpec> emptyPartitionSpecsById = new HashMap<Integer, PartitionSpec>() {

        {
            put(0, PartitionSpec.builderFor(schema).build());
        }
    };
    assertManifest(manifestFiles, emptyPartitionSpecsById, Expressions.alwaysTrue(), manifestFiles);
    // test long partition spec
    HashMap<Integer, PartitionSpec> longPartitionSpecsById = new HashMap<Integer, PartitionSpec>() {

        {
            put(0, PartitionSpec.builderFor(schema).identity("par").build());
        }
    };
    // 1. par > 10
    UnboundPredicate<Long> e1 = Expressions.greaterThan("par", 10L);
    assertManifest(manifestFiles, longPartitionSpecsById, Expressions.and(Expressions.alwaysTrue(), e1), manifestFiles);
    // 2. 10 < par < 90
    UnboundPredicate<Long> e2 = Expressions.greaterThan("par", 90L);
    assertManifest(manifestFiles, longPartitionSpecsById, Expressions.and(e1, e2), manifestFiles);
    // 3. 10 < par < 300
    UnboundPredicate<Long> e3 = Expressions.lessThan("par", 300L);
    assertManifest(manifestFiles, longPartitionSpecsById, Expressions.and(e1, e3), Collections.singletonList(f1));
    // 4. 10 < par < 400
    UnboundPredicate<Long> e4 = Expressions.lessThan("par", 400L);
    ArrayList<ManifestFile> expect1 = new ArrayList<ManifestFile>() {

        {
            add(f1);
            add(f2);
        }
    };
    assertManifest(manifestFiles, longPartitionSpecsById, Expressions.and(e1, e4), expect1);
    // 5. 10 < par < 501
    UnboundPredicate<Long> e5 = Expressions.lessThan("par", 501L);
    assertManifest(manifestFiles, longPartitionSpecsById, Expressions.and(e1, e5), manifestFiles);
    // 6. 200 < par < 501
    UnboundPredicate<Long> e6 = Expressions.greaterThan("par", 200L);
    ArrayList<ManifestFile> expect2 = new ArrayList<ManifestFile>() {

        {
            add(f2);
            add(f3);
        }
    };
    assertManifest(manifestFiles, longPartitionSpecsById, Expressions.and(e6, e5), expect2);
    // 7. par > 600
    UnboundPredicate<Long> e7 = Expressions.greaterThan("par", 600L);
    assertManifest(manifestFiles, longPartitionSpecsById, Expressions.and(Expressions.alwaysTrue(), e7), Collections.emptyList());
    // 8. par < 100
    UnboundPredicate<Long> e8 = Expressions.lessThan("par", 100L);
    assertManifest(manifestFiles, longPartitionSpecsById, Expressions.and(Expressions.alwaysTrue(), e8), Collections.emptyList());
}

@Test
public void testIsNewClickHouseDriver() {
    try {
        Method method = JdbcClickHouseClient.class.getDeclaredMethod("isNewClickHouseDriver", String.class);
        method.setAccessible(true);
        // Valid test cases
        // Major version 0, Minor version 5
        Assert.assertTrue((boolean) method.invoke(null, "0.5.0"));
        // Major version 1
        Assert.assertTrue((boolean) method.invoke(null, "1.0.0"));
        // Major version 0, Minor version 6
        Assert.assertTrue((boolean) method.invoke(null, "0.6.3 (revision: a6a8a22)"));
        // Major version 0, Minor version 4
        Assert.assertFalse((boolean) method.invoke(null, "0.4.2 (revision: 1513b27)"));
        // Invalid version formats
        try {
            // Invalid version format
            method.invoke(null, "invalid.version");
            Assert.fail("Expected JdbcClientException for invalid version 'invalid.version'");
        } catch (Exception e) {
            Assert.assertTrue(e.getCause() instanceof JdbcClientException);
            Assert.assertTrue(e.getCause().getMessage().contains("Invalid clickhouse driver version format"));
        }
        try {
            // Empty version
            method.invoke(null, "");
            Assert.fail("Expected JdbcClientException for empty version");
        } catch (Exception e) {
            Assert.assertTrue(e.getCause() instanceof JdbcClientException);
            Assert.assertTrue(e.getCause().getMessage().contains("Invalid clickhouse driver version format"));
        }
        try {
            // Null version
            method.invoke(null, (Object) null);
            Assert.fail("Expected JdbcClientException for null version");
        } catch (Exception e) {
            Assert.assertTrue(e.getCause() instanceof JdbcClientException);
            Assert.assertTrue(e.getCause().getMessage().contains("Driver version cannot be null"));
        }
    } catch (Exception e) {
        Assert.fail("Exception occurred while testing isNewClickHouseDriver: " + e.getMessage());
    }
}

