@Test
public void testProcessCompatibleProperties() {
    // Create a properties map with lower_case_table_names
    jdbcExternalCatalog.getCatalogProperty().addProperty("lower_case_table_names", "true");
    // Call processCompatibleProperties
    jdbcExternalCatalog.setDefaultPropsIfMissing(true);
    // Assert that lower_case_meta_names is present and has the correct value
    Assert.assertTrue(jdbcExternalCatalog.getCatalogProperty().getProperties().containsKey("lower_case_meta_names"));
    Assert.assertEquals("true", jdbcExternalCatalog.getCatalogProperty().getProperties().get("lower_case_meta_names"));
    // Assert that lower_case_table_names is not present
    Assert.assertFalse(jdbcExternalCatalog.getCatalogProperty().getProperties().containsKey("lower_case_table_names"));
    jdbcExternalCatalog.getCatalogProperty().addProperty("lower_case_table_names", "true");
    IllegalArgumentException exceptione = Assert.assertThrows(IllegalArgumentException.class, () -> jdbcExternalCatalog.setDefaultPropsIfMissing(false));
    Assert.assertEquals("Jdbc catalog property lower_case_table_names is not supported, please use lower_case_meta_names instead.", exceptione.getMessage());
    jdbcExternalCatalog.getCatalogProperty().deleteProperty("lower_case_table_names");
}

