    //         0L))
    add(Range.equal(trinoConnectorColumnMetadataMap.get("c_long_timestamp").getType(), new LongTimestamp(1000001L, 0))).add(Range.equal(trinoConnectorColumnMetadataMap.get("c_long_timestamp_timezone").getType(), LongTimestampWithTimeZone.fromEpochMillisAndFraction(1000L, 1000000, TimeZoneKey.getTimeZoneKey("Asia/Shanghai")))).build();
    for (int i = 0; i < slotRefs.size(); i++) {
        final String colName = slotRefs.get(i).getColumnName();
        Domain inDomain = Domain.create(ValueSet.ofRanges(Lists.newArrayList(expectRanges.get(i))), false);
        Domain notInDomain = Domain.create(ValueSet.all(trinoConnectorColumnMetadataMap.get(colName).getType()).subtract(ValueSet.ofRanges(expectRanges.get(i))), false);
        TupleDomain<ColumnHandle> inTupleDomain = TupleDomain.withColumnDomains(ImmutableMap.of(trinoConnectorColumnHandleMap.get(colName), inDomain));
        TupleDomain<ColumnHandle> notInTupleDomain = TupleDomain.withColumnDomains(ImmutableMap.of(trinoConnectorColumnHandleMap.get(colName), notInDomain));
