@Test
public void testCastConvertEsDsl() {
    FloatLiteral floatLiteral = new FloatLiteral(3.14);
    CastExpr castExpr = new CastExpr(Type.INT, floatLiteral);
    BinaryPredicate castPredicate = new BinaryPredicate(Operator.EQ, castExpr, new IntLiteral(3));
    List<Expr> notPushDownList = new ArrayList<>();
    Map<String, String> fieldsContext = new HashMap<>();
    Map<String, String> col2typeMap = new HashMap<>();
    BuilderOptions builderOptions = BuilderOptions.builder().likePushDown(true).build();
    Assertions.assertNull(QueryBuilders.toEsDsl(castPredicate, notPushDownList, fieldsContext, builderOptions, col2typeMap));
    Assertions.assertEquals(1, notPushDownList.size());
    SlotRef k2 = new SlotRef(null, "k2");
    IntLiteral intLiteral = new IntLiteral(5);
    BinaryPredicate eqPredicate = new BinaryPredicate(Operator.EQ, k2, intLiteral);
    CompoundPredicate compoundPredicate = new CompoundPredicate(CompoundPredicate.Operator.OR, castPredicate, eqPredicate);
    QueryBuilders.toEsDsl(compoundPredicate, notPushDownList, fieldsContext, builderOptions, col2typeMap);
    Assertions.assertEquals(3, notPushDownList.size());
    SlotRef k3 = new SlotRef(null, "k3");
    k3.setType(Type.FLOAT);
    CastExpr castDoubleExpr = new CastExpr(Type.DOUBLE, k3);
    BinaryPredicate castDoublePredicate = new BinaryPredicate(Operator.GE, castDoubleExpr, new FloatLiteral(3.0, Type.DOUBLE));
    QueryBuilders.toEsDsl(castDoublePredicate, notPushDownList, fieldsContext, builderOptions, col2typeMap);
    Assertions.assertEquals(3, notPushDownList.size());
    SlotRef k4 = new SlotRef(null, "k4");
    k4.setType(Type.FLOAT);
    CastExpr castFloatExpr = new CastExpr(Type.FLOAT, k4);
    BinaryPredicate castFloatPredicate = new BinaryPredicate(Operator.GE, new FloatLiteral(3.0, Type.FLOAT), castFloatExpr);
    QueryBuilders.QueryBuilder queryBuilder = QueryBuilders.toEsDsl(castFloatPredicate, notPushDownList, fieldsContext, builderOptions, col2typeMap);
    Assertions.assertEquals("{\"range\":{\"k4\":{\"lte\":3.0}}}", queryBuilder.toJson());
    Assertions.assertEquals(3, notPushDownList.size());
    castFloatPredicate = new BinaryPredicate(Operator.LE, new FloatLiteral(3.0, Type.FLOAT), castFloatExpr);
    queryBuilder = QueryBuilders.toEsDsl(castFloatPredicate, notPushDownList, fieldsContext, builderOptions, col2typeMap);
    Assertions.assertEquals("{\"range\":{\"k4\":{\"gte\":3.0}}}", queryBuilder.toJson());
    Assertions.assertEquals(3, notPushDownList.size());
    castFloatPredicate = new BinaryPredicate(Operator.LT, new FloatLiteral(3.0, Type.FLOAT), castFloatExpr);
    queryBuilder = QueryBuilders.toEsDsl(castFloatPredicate, notPushDownList, fieldsContext, builderOptions, col2typeMap);
    Assertions.assertEquals("{\"range\":{\"k4\":{\"gt\":3.0}}}", queryBuilder.toJson());
    Assertions.assertEquals(3, notPushDownList.size());
    castFloatPredicate = new BinaryPredicate(Operator.GT, new FloatLiteral(3.0, Type.FLOAT), castFloatExpr);
    queryBuilder = QueryBuilders.toEsDsl(castFloatPredicate, notPushDownList, fieldsContext, builderOptions, col2typeMap);
    Assertions.assertEquals("{\"range\":{\"k4\":{\"lt\":3.0}}}", queryBuilder.toJson());
    Assertions.assertEquals(3, notPushDownList.size());
}

