@Test
public void testAlterMTMV() throws Exception {
    createDatabaseAndUse("test");
    createTable("CREATE TABLE `stu` (`sid` int(32) NULL, `sname` varchar(32) NULL)\n" + "ENGINE=OLAP\n" + "DUPLICATE KEY(`sid`)\n" + "DISTRIBUTED BY HASH(`sid`) BUCKETS 1\n" + "PROPERTIES ('replication_allocation' = 'tag.location.default: 1')");
    createMvByNereids("CREATE MATERIALIZED VIEW mv_a BUILD IMMEDIATE REFRESH COMPLETE ON COMMIT\n" + "DISTRIBUTED BY HASH(`sid`) BUCKETS 1\n" + "PROPERTIES ('replication_allocation' = 'tag.location.default: 1') " + "AS select * from stu limit 1");
    alterMv("ALTER MATERIALIZED VIEW mv_a RENAME mv_b");
    MTMVRelationManager relationManager = Env.getCurrentEnv().getMtmvService().getRelationManager();
    Table table = Env.getCurrentInternalCatalog().getDb("test").get().getTableOrMetaException("stu");
    Set<MTMV> allMTMVs = relationManager.getAllMTMVs(Lists.newArrayList(new BaseTableInfo(table)));
    boolean hasMvA = false;
    boolean hasMvB = false;
    for (MTMV mtmv : allMTMVs) {
        if ("mv_a".equals(mtmv.getName())) {
            hasMvA = true;
        }
        if ("mv_b".equals(mtmv.getName())) {
            hasMvB = true;
        }
    }
    Assertions.assertFalse(hasMvA);
    Assertions.assertTrue(hasMvB);
    createTable("CREATE TABLE `stu1` (`sid` int(32) NULL, `sname` varchar(32) NULL)\n" + "ENGINE=OLAP\n" + "DUPLICATE KEY(`sid`)\n" + "DISTRIBUTED BY HASH(`sid`) BUCKETS 1\n" + "PROPERTIES ('replication_allocation' = 'tag.location.default: 1')");
    DdlException exception = Assertions.assertThrows(DdlException.class, () -> alterTableSync("ALTER TABLE stu1 REPLACE WITH TABLE mv_b PROPERTIES('swap' = 'true')"));
    Assertions.assertEquals("errCode = 2, detailMessage = replace table[mv_b] cannot be a materialized view", exception.getMessage());
}

