        e.printStackTrace();
    }
    // test Select_PRIV with col
    grantStmt = new GrantStmt(userIdentity, null, new TablePattern("db1", "tbl1"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.SELECT_PRIV, Lists.newArrayList("a", "b"))));
    try {
        grantStmt.analyze(analyzer);
        auth.grant(grantStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // check has select priv of column 'a'
    try {
        accessManager.checkColumnsPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "db1", "tbl1", Sets.newHashSet("a"), PrivPredicate.SELECT);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // check has select priv of column 'c'
    try {
        accessManager.checkColumnsPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "db1", "tbl1", Sets.newHashSet("c"), PrivPredicate.SELECT);
        Assert.fail();
    } catch (UserException e) {
        e.printStackTrace();
    }
    // check has load priv of column 'a'
    try {
        accessManager.checkColumnsPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "db1", "tbl1", Sets.newHashSet("a"), PrivPredicate.LOAD);
        Assert.fail();
    } catch (UserException e) {
