    }
    // check 'create_priv' use checkColumnsPriv
    try {
        accessManager.checkColumnsPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "db1", "tbl1", Sets.newHashSet("a"), PrivPredicate.CREATE);
        Assert.fail();
    } catch (Exception e) {
        e.printStackTrace();
    }
    // check show priv on ctl when has col priv
    boolean hasPriv = accessManager.checkCtlPriv(userIdentity, Auth.DEFAULT_CATALOG, PrivPredicate.SHOW);
    if (!hasPriv) {
        Assert.fail();
    }
    // check show priv on db when has col priv
    hasPriv = accessManager.checkDbPriv(userIdentity, Auth.DEFAULT_CATALOG, "db1", PrivPredicate.SHOW);
    if (!hasPriv) {
        Assert.fail();
    }
    // check show priv on tbl when has col priv
    hasPriv = accessManager.checkTblPriv(userIdentity, Auth.DEFAULT_CATALOG, "db1", "tbl1", PrivPredicate.SHOW);
    if (!hasPriv) {
        Assert.fail();
    }
    // check select priv on tbl when has col priv
    hasPriv = accessManager.checkTblPriv(userIdentity, Auth.DEFAULT_CATALOG, "db1", "tbl1", PrivPredicate.SELECT);
    if (hasPriv) {
        Assert.fail();
    }
}

@Test
public void testGrantRole() {
    UserIdentity userIdentity = new UserIdentity("testUser", "%");
    UserDesc userDesc = new UserDesc(userIdentity, "12345", true);
    String role = "role1";
    // 1. create role
    CreateRoleStmt createRoleStmt = new CreateRoleStmt(role);
    try {
        createRoleStmt.analyze(analyzer);
        auth.createRole(createRoleStmt);
    } catch (UserException e1) {
        e1.printStackTrace();
        Assert.fail();
    }
    // grant select_priv on db 'db1' to role 'role1'
    GrantStmt grantStmt = new GrantStmt(null, role, new TablePattern("db1", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.SELECT_PRIV)));
    try {
        grantStmt.analyze(analyzer);
        auth.grant(grantStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // create user with no role
    CreateUserStmt createUserStmt = new CreateUserStmt(false, userDesc, null);
    try {
        createUserStmt.analyze(analyzer);
        auth.createUser(createUserStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertFalse(accessManager.checkDbPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "db1", PrivPredicate.SELECT));
    // grant 'role1' to testUser
    grantStmt = new GrantStmt(Lists.newArrayList(role), userIdentity);
    try {
        grantStmt.analyze(analyzer);
        auth.grant(grantStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(accessManager.checkDbPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "db1", PrivPredicate.SELECT));
    // revoke 'role1' from testUser
    RevokeStmt revokeStmt = new RevokeStmt(Lists.newArrayList(role), userIdentity);
    try {
        revokeStmt.analyze(analyzer);
        auth.revoke(revokeStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertFalse(accessManager.checkDbPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "db1", PrivPredicate.SELECT));
    // grant not exist role to testUser
    grantStmt = new GrantStmt(Lists.newArrayList("norole"), userIdentity);
    try {
        grantStmt.analyze(analyzer);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    boolean hasException = false;
    try {
        auth.grant(grantStmt);
    } catch (DdlException e) {
        e.printStackTrace();
        hasException = true;
    }
    Assert.assertTrue(hasException);
}

@Test
public void testResource() throws UserException {
    UserIdentity userIdentity = new UserIdentity("testUser", "%");
    String role = "role0";
    String resourceName = "spark0";
    ResourcePattern resourcePattern = new ResourcePattern(resourceName, ResourceTypeEnum.GENERAL);
    String anyResource = "%";
    ResourcePattern anyResourcePattern = new ResourcePattern(anyResource, ResourceTypeEnum.GENERAL);
    List<AccessPrivilegeWithCols> usagePrivileges = Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.USAGE_PRIV));
    List<AccessPrivilegeWithCols> grantPrivileges = Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.GRANT_PRIV));
    UserDesc userDesc = new UserDesc(userIdentity, "12345", true);
    // ------ grant|revoke resource to|from user ------
    // 1. create user with no role
    CreateUserStmt createUserStmt = new CreateUserStmt(false, userDesc, null);
    try {
        createUserStmt.analyze(analyzer);
        auth.createUser(createUserStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // 2. grant usage_priv on resource 'spark0' to 'testUser'@'%'
    GrantStmt grantStmt = new GrantStmt(userIdentity, null, resourcePattern, usagePrivileges, ResourceTypeEnum.GENERAL);
    try {
        grantStmt.analyze(analyzer);
        auth.grant(grantStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(accessManager.checkResourcePriv(userIdentity, resourceName, PrivPredicate.USAGE));
    Assert.assertFalse(accessManager.checkGlobalPriv(userIdentity, PrivPredicate.USAGE));
    // 3. revoke usage_priv on resource 'spark0' from 'testUser'@'%'
    RevokeStmt revokeStmt = new RevokeStmt(userIdentity, null, resourcePattern, usagePrivileges, ResourceTypeEnum.GENERAL);
    try {
        revokeStmt.analyze(analyzer);
        auth.revoke(revokeStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertFalse(accessManager.checkResourcePriv(userIdentity, resourceName, PrivPredicate.USAGE));
    Assert.assertFalse(accessManager.checkGlobalPriv(userIdentity, PrivPredicate.USAGE));
    // 3.1 grant 'notBelongToResourcePrivileges' on resource 'spark0' to 'testUser'@'%'
    for (int i = 0; i < Privilege.notBelongToResourcePrivileges.length; i++) {
        List<AccessPrivilegeWithCols> notAllowedPrivileges = Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.fromName(Privilege.notBelongToResourcePrivileges[i].getName())));
        grantStmt = new GrantStmt(userIdentity, null, resourcePattern, notAllowedPrivileges, ResourceTypeEnum.GENERAL);
        try {
            grantStmt.analyze(analyzer);
            Assert.fail(String.format("Can not grant/revoke %s to/from any other users or roles", Privilege.notBelongToResourcePrivileges[i]));
        } catch (UserException e) {
            e.printStackTrace();
        }
    }
    // 4. drop user
    DropUserStmt dropUserStmt = new DropUserStmt(userIdentity);
    try {
        dropUserStmt.analyze(analyzer);
        auth.dropUser(dropUserStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // ------ grant|revoke resource to|from role ------
    // 1. create role
    CreateRoleStmt roleStmt = new CreateRoleStmt(role);
    try {
        roleStmt.analyze(analyzer);
        auth.createRole(roleStmt);
    } catch (UserException e1) {
        e1.printStackTrace();
        Assert.fail();
    }
    // grant usage_priv on resource 'spark0' to role 'role0'
    grantStmt = new GrantStmt(null, role, resourcePattern, usagePrivileges, ResourceTypeEnum.GENERAL);
    try {
        grantStmt.analyze(analyzer);
        auth.grant(grantStmt);
    } catch (UserException e1) {
        e1.printStackTrace();
        Assert.fail();
    }
    // 2. create user with role
    createUserStmt = new CreateUserStmt(false, userDesc, role);
    try {
        createUserStmt.analyze(analyzer);
        auth.createUser(createUserStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(accessManager.checkResourcePriv(userIdentity, resourceName, PrivPredicate.USAGE));
    Assert.assertFalse(accessManager.checkGlobalPriv(userIdentity, PrivPredicate.USAGE));
    // 3. revoke usage_priv on resource 'spark0' from role 'role0'
    revokeStmt = new RevokeStmt(null, role, resourcePattern, usagePrivileges, ResourceTypeEnum.GENERAL);
    try {
        revokeStmt.analyze(analyzer);
        auth.revoke(revokeStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // also revoke from user with this role
    Assert.assertFalse(accessManager.checkResourcePriv(userIdentity, resourceName, PrivPredicate.USAGE));
    Assert.assertFalse(accessManager.checkGlobalPriv(userIdentity, PrivPredicate.USAGE));
    // 4. drop user and role
    dropUserStmt = new DropUserStmt(userIdentity);
    try {
        dropUserStmt.analyze(analyzer);
        auth.dropUser(dropUserStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    DropRoleStmt dropRoleStmt = new DropRoleStmt(role);
    try {
        dropRoleStmt.analyze(analyzer);
        auth.dropRole(dropRoleStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // ------ grant|revoke any resource to|from user ------
    // 1. create user with no role
    createUserStmt = new CreateUserStmt(false, userDesc, null);
    try {
        createUserStmt.analyze(analyzer);
        auth.createUser(createUserStmt);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // 2. grant usage_priv on resource '*' to 'testUser'@'%'
