void testMaterializingCost() {
    String sql = "select T1.id, T2.id, T2.score from T1 left join T2 " + "on T1.id = T2.id";
    connectContext.getSessionVariable().setDisableNereidsRules("PRUNE_EMPTY_PARTITION");
