@Test
public void testHintWithReorderCrossJoin() {
    String sql = "select t1.a , t2.x, t.x from " + "t1 join [shuffle] t2, (select x from t3) t where t1.a=t.x and t2.x=t.x";
    PlanChecker.from(connectContext).checkExplain(sql, planner -> {
        Plan plan = planner.getOptimizedPlan();
        MatchingUtils.assertMatches(plan, physicalResultSink(physicalDistribute(physicalHashJoin(physicalDistribute(physicalHashJoin(physicalProject(), physicalDistribute())).when(dis -> {
            DistributionSpec spec = dis.getDistributionSpec();
            Assertions.assertInstanceOf(DistributionSpecHash.class, spec);
            DistributionSpecHash hashSpec = (DistributionSpecHash) spec;
            Assertions.assertEquals(ShuffleType.EXECUTION_BUCKETED, hashSpec.getShuffleType());
            return true;
