    HyperGraph hyperGraph = new HyperGraphBuilder().init(10, 20, 30, 40, 50).addEdge(JoinType.INNER_JOIN, 0, 1).addEdge(JoinType.INNER_JOIN, 0, 2).addEdge(JoinType.INNER_JOIN, 0, 3).addEdge(JoinType.INNER_JOIN, 0, 4).build();
    GraphSimplifier graphSimplifier = new GraphSimplifier(hyperGraph);
    List<Pair<Long, Long>> steps = ImmutableList.<Pair<Long, Long>>builder().add(// 04   - 1
    Pair.of(17L, 2L)).add(// 04   - 2
