    MappedRelation[] right = new MappedRelation[] { mr191, mr194, mr195 };
    List<Pair<MappedRelation[], MappedRelation[]>> uniquePermutation = RelationMapping.getUniquePermutation(left, right, 10);
    Set<BiMap<Integer, Integer>> generatedMappedSet = generateDirectPermutations(uniquePermutation);
    Set<BiMap<Integer, Integer>> exceptedSet = new HashSet<>();
    BiMap<Integer, Integer> eachMap = HashBiMap.create();
    eachMap.put(1, 195);
    eachMap.put(4, 194);
    eachMap.put(5, 191);
    exceptedSet.add(eachMap);
    eachMap = HashBiMap.create();
    eachMap.put(1, 194);
    eachMap.put(4, 191);
    eachMap.put(5, 195);
    exceptedSet.add(eachMap);
    eachMap = HashBiMap.create();
    eachMap.put(1, 194);
    eachMap.put(4, 195);
    eachMap.put(5, 191);
    exceptedSet.add(eachMap);
    eachMap = HashBiMap.create();
    eachMap.put(1, 195);
    eachMap.put(4, 191);
    eachMap.put(5, 194);
    exceptedSet.add(eachMap);
    eachMap = HashBiMap.create();
    eachMap.put(1, 191);
    eachMap.put(4, 194);
    eachMap.put(5, 195);
    exceptedSet.add(eachMap);
    eachMap = HashBiMap.create();
    eachMap.put(1, 191);
    eachMap.put(4, 195);
    eachMap.put(5, 194);
    exceptedSet.add(eachMap);
    Assertions.assertEquals(exceptedSet, generatedMappedSet);
}

