    sql = "use a";
    plan = nereidsParser.parseSingle(sql);
    Assertions.assertEquals(plan.stmtType(), StmtType.USE);
    sql = "CREATE TABLE tbl (`id` INT NOT NULL) DISTRIBUTED BY HASH(`id`) BUCKETS 1";
