    leftMap.put(new ExprId(0), 0);
    leftMap.put(new ExprId(1), 0);
    PhysicalProperties left = new PhysicalProperties(new DistributionSpecHash(Lists.newArrayList(new ExprId(0)), ShuffleType.NATURAL, 0, Sets.newHashSet(0L), ImmutableList.of(Sets.newHashSet(new ExprId(0), new ExprId(1))), leftMap));
    PhysicalProperties right = new PhysicalProperties(DistributionSpecReplicated.INSTANCE, new OrderSpec(Lists.newArrayList(new OrderKey(new SlotReference("ignored", IntegerType.INSTANCE), true, true))));
