    requireMap.put(new ExprId(4), 0);
    requireMap.put(new ExprId(3), 1);
    requireMap.put(new ExprId(5), 1);
    DistributionSpecHash join = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(5)), ShuffleType.REQUIRE, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1), new ExprId(4)), Sets.newHashSet(new ExprId(3), new ExprId(5))), requireMap);
    Map<ExprId, Integer> expectedMap = Maps.newHashMap();
