@Test
void testQualify() {
    connectContext.getSessionVariable().setDisableNereidsRules("ELIMINATE_AGG_ON_EMPTYRELATION");
    String sql = "select year + 1, country from sales where year >= 2000 qualify row_number() over (order by profit) > 1";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalResultSink(logicalProject(logicalFilter(logicalWindow(logicalEmptyRelation())).when(filter -> filter.toString().contains("predicates=(row_number() OVER(ORDER BY profit asc null first)#5 > 1)")))));
    sql = "select year + 1, country, row_number() over (order by year) as rk from sales where year >= 2000 qualify rk > profit";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalResultSink(logicalProject(logicalFilter(logicalWindow(logicalEmptyRelation())).when(filter -> filter.toString().contains("predicates=(rk#5 > cast(profit#3 as BIGINT))")))));
    sql = "select year + 1, country from sales where year >= 2000 group by year,country qualify rank() over (order by year) > 1";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalResultSink(logicalProject(logicalFilter(logicalWindow(logicalProject(logicalAggregate(logicalEmptyRelation())))).when(filter -> filter.toString().contains("predicates=(rank() OVER(ORDER BY year asc null first)#5 > 1)")))));
    sql = "select year + 1, country, sum(profit) as total from sales where year >= 2000 group by year,country having sum(profit) > 100 qualify row_number() over (order by year) > 1";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalResultSink(logicalProject(logicalFilter(logicalWindow(logicalProject(logicalFilter(logicalAggregate(logicalEmptyRelation())).when(filter -> filter.toString().contains("predicates=(total#5 > 100)"))))).when(filter -> filter.toString().contains("predicates=(row_number() OVER(ORDER BY year asc null first)#6 > 1)")))));
    sql = "select distinct year + 1,country from sales qualify row_number() over (order by profit + 1) > 1";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalResultSink(logicalAggregate(logicalProject(logicalFilter(logicalWindow(logicalEmptyRelation())).when(filter -> filter.toString().contains("predicates=(row_number() OVER(ORDER BY (profit + 1) asc null first)#5 > 1)"))))));
    sql = "select distinct year + 1 as year,country from sales group by year, country qualify row_number() over (order by year) > 1";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalResultSink(logicalAggregate(logicalProject(logicalFilter(logicalWindow(logicalProject(logicalAggregate(logicalEmptyRelation())))).when(filter -> filter.toString().contains("predicates=(row_number() OVER(ORDER BY year asc null first)#5 > 1)"))))));
    sql = "select distinct year,country,rank() over (order by year) from sales having sum(profit) > 100 qualify row_number() over (order by year) > 1";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalResultSink(logicalProject(logicalFilter(logicalAggregate(logicalProject(logicalFilter(logicalWindow(logicalEmptyRelation())).when(filter -> filter.toString().contains("predicates=(row_number() OVER(ORDER BY year asc null first)#5 > 1)"))))).when(filter -> filter.toString().contains("predicates=(sum(profit)#6 > 100)")))));
    ExceptionChecker.expectThrowsWithMsg(AnalysisException.class, "qualify only used for window expression", () -> PlanChecker.from(connectContext).analyze("select year + 1, country from sales where year >= 2000 qualify year > 1"));
}

