@Test
void testLOJWithGroupBy() {
    connectContext.getSessionVariable().setDisableNereidsRules("INFER_PREDICATES,PRUNE_EMPTY_PARTITION");
    CascadesContext c1 = createCascadesContext("select * from T1", connectContext);
    Plan p1 = PlanChecker.from(c1).analyze().rewrite().getPlan().child(0);
    CascadesContext c2 = createCascadesContext("select * from T1 left outer join (select id from T2 group by id) T2 " + "on T1.id = T2.id ", connectContext);
    Plan p2 = PlanChecker.from(c2).analyze().rewrite().applyExploration(RuleSet.BUSHY_TREE_JOIN_REORDER).getAllPlan().get(0).child(0);
    CascadesContext c3 = createCascadesContext("select * from T1 left outer join (select id as id2 from T2 group by id) T2 " + "on T1.id = T2.id2 ", connectContext);
    Plan p3 = PlanChecker.from(c3).analyze().rewrite().applyExploration(RuleSet.BUSHY_TREE_JOIN_REORDER).getAllPlan().get(0).child(0);
    HyperGraph h1 = HyperGraph.builderForMv(p1).build();
    HyperGraph h2 = HyperGraph.builderForMv(p2).build();
    HyperGraph h3 = HyperGraph.builderForMv(p3).build();
    ComparisonResult res = HyperGraphComparator.isLogicCompatible(h1, h2, constructContext(p1, p2, c1));
    Assertions.assertTrue(!res.isInvalid());
    Assertions.assertTrue(!HyperGraphComparator.isLogicCompatible(h1, h3, constructContext(p1, p2, c1)).isInvalid());
