    assertRewrite(new GreaterThanEqual(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThanEqual(tinyIntSlot, new TinyIntLiteral((byte) 13)));
    assertRewrite(new LessThan(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThan(tinyIntSlot, new TinyIntLiteral((byte) 13)));
    assertRewrite(new LessThanEqual(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThanEqual(tinyIntSlot, new TinyIntLiteral((byte) 12)));
    // tiny int, literal exceeds data type limit
    assertRewrite(new EqualTo(new Cast(tinyIntSlot, FloatType.INSTANCE), new FloatLiteral(200.0f)), ExpressionUtils.falseOrNull(tinyIntSlot));
    assertRewrite(new EqualTo(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.0f)), ExpressionUtils.falseOrNull(tinyIntSlot));
    assertRewrite(new EqualTo(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), ExpressionUtils.falseOrNull(tinyIntSlot));
    assertRewrite(new NullSafeEqual(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), BooleanLiteral.FALSE);
    assertRewrite(new GreaterThan(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), ExpressionUtils.falseOrNull(tinyIntSlot));
    assertRewrite(new GreaterThanEqual(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), ExpressionUtils.falseOrNull(tinyIntSlot));
    assertRewrite(new LessThan(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), ExpressionUtils.trueOrNull(tinyIntSlot));
    assertRewrite(new LessThanEqual(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), ExpressionUtils.trueOrNull(tinyIntSlot));
    // small int
    assertRewrite(new EqualTo(new Cast(smallIntSlot, FloatType.INSTANCE), new FloatLiteral(12.0f)), new EqualTo(smallIntSlot, new SmallIntLiteral((short) 12)));
    assertRewrite(new EqualTo(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.0f)), new EqualTo(smallIntSlot, new SmallIntLiteral((short) 12)));
    assertRewrite(new EqualTo(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), ExpressionUtils.falseOrNull(smallIntSlot));
    assertRewrite(new NullSafeEqual(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), BooleanLiteral.FALSE);
    assertRewrite(new GreaterThan(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThan(smallIntSlot, new SmallIntLiteral((short) 12)));
    assertRewrite(new GreaterThanEqual(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThanEqual(smallIntSlot, new SmallIntLiteral((short) 13)));
    assertRewrite(new LessThan(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThan(smallIntSlot, new SmallIntLiteral((short) 13)));
    assertRewrite(new LessThanEqual(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThanEqual(smallIntSlot, new SmallIntLiteral((short) 12)));
    // int
    assertRewrite(new EqualTo(new Cast(intSlot, FloatType.INSTANCE), new FloatLiteral(12.0f)), new EqualTo(intSlot, new IntegerLiteral(12)));
    assertRewrite(new EqualTo(new Cast(intSlot, DoubleType.INSTANCE), new DoubleLiteral(12.0f)), new EqualTo(intSlot, new IntegerLiteral(12)));
