    assertRewrite(new LessThan(new Cast(intSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThan(intSlot, new IntegerLiteral(13)));
    assertRewrite(new LessThanEqual(new Cast(intSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThanEqual(intSlot, new IntegerLiteral(12)));
    // big int
    assertRewrite(new EqualTo(new Cast(bigIntSlot, FloatType.INSTANCE), new FloatLiteral(12.0f)), new EqualTo(bigIntSlot, new BigIntLiteral(12L)));
    assertRewrite(new EqualTo(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.0f)), new EqualTo(bigIntSlot, new BigIntLiteral(12L)));
    assertRewrite(new EqualTo(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), ExpressionUtils.falseOrNull(bigIntSlot));
