    assertRewrite(new GreaterThanEqual(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThanEqual(bigIntSlot, new BigIntLiteral(13L)));
    assertRewrite(new LessThan(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThan(bigIntSlot, new BigIntLiteral(13L)));
    assertRewrite(new LessThanEqual(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThanEqual(bigIntSlot, new BigIntLiteral(12L)));
}

