@Test
public void test() {
    executor = new ExpressionRuleExecutor(ImmutableList.of(bottomUp(FoldConstantRule.INSTANCE, SimplifyInPredicate.INSTANCE)));
    Map<String, Slot> mem = Maps.newHashMap();
    Expression rewrittenExpression = PARSER.parseExpression("cast(CA as DATETIME) in ('1992-01-31 00:00:00', '1992-02-01 00:00:00')");
    // after parse and type coercion: CAST(CAST(CA AS DATETIMEV2(0)) AS DATETIMEV2(6)) IN ('1992-01-31 00:00:00.000000', '1992-02-01 00:00:00.000000')
    rewrittenExpression = typeCoercion(replaceUnboundSlot(rewrittenExpression, mem));
    // after first rewrite: CAST(CA AS DATETIMEV2(0)) IN ('1992-01-31 00:00:00', '1992-02-01 00:00:00')
    rewrittenExpression = executor.rewrite(rewrittenExpression, context);
    // after second rewrite: CA IN ('1992-01-31', '1992-02-01')
    rewrittenExpression = executor.rewrite(rewrittenExpression, context);
    Expression expectedExpression = PARSER.parseExpression("CA in (cast('1992-01-31' as date), cast('1992-02-01' as date))");
    expectedExpression = replaceUnboundSlot(expectedExpression, mem);
    executor = new ExpressionRuleExecutor(ImmutableList.of(bottomUp(FoldConstantRule.INSTANCE)));
    expectedExpression = executor.rewrite(expectedExpression, context);
    Assertions.assertEquals(expectedExpression, rewrittenExpression);
}

@Test
public void testRangeInference() {
    ValueDesc valueDesc = getValueDesc("TA IS NULL");
    Assertions.assertInstanceOf(UnknownValue.class, valueDesc);
    List<ValueDesc> sourceValues = ((UnknownValue) valueDesc).getSourceValues();
    Assertions.assertEquals(0, sourceValues.size());
    Assertions.assertEquals("TA IS NULL", valueDesc.getReference().toSql());
    valueDesc = getValueDesc("TA IS NULL AND TB IS NULL AND NULL");
    Assertions.assertInstanceOf(UnknownValue.class, valueDesc);
    sourceValues = ((UnknownValue) valueDesc).getSourceValues();
    Assertions.assertEquals(3, sourceValues.size());
    Assertions.assertInstanceOf(EmptyValue.class, sourceValues.get(0));
    Assertions.assertInstanceOf(EmptyValue.class, sourceValues.get(1));
    Assertions.assertEquals("TA", sourceValues.get(0).getReference().toSql());
    Assertions.assertEquals("TB", sourceValues.get(1).getReference().toSql());
}

