    plan = new LogicalOlapTableSink<>(new Database(), scan.getTable(), scan.getTable().getBaseSchema(), new ArrayList<>(), plan.getOutput().stream().map(NamedExpression.class::cast).collect(Collectors.toList()), false, DMLCommandType.NONE, plan);
    PlanChecker.from(MemoTestUtils.createConnectContext(), plan).disableNereidsRules("PRUNE_EMPTY_PARTITION").rewrite().nonMatch(logicalSort()).matches(logicalTopN());
