void testFindHashCondition() {
    Slot studentId = studentScan.getOutput().get(0);
    Slot gender = studentScan.getOutput().get(1);
    Slot scoreId = scoreScan.getOutput().get(0);
    Slot cid = scoreScan.getOutput().get(1);
    // a=b
    Expression eq1 = new EqualTo(studentId, scoreId);
    // a=1
    Expression eq2 = new EqualTo(studentId, new IntegerLiteral(1));
    Expression eq3 = new EqualTo(new Add(studentId, new IntegerLiteral(1)), cid);
    Expression or = new Or(new EqualTo(scoreId, studentId), new EqualTo(gender, cid));
    Expression less = new LessThan(scoreId, studentId);
    Expression eq4 = new EqualTo(studentId, new Add(scoreId, cid));
    Expression eq5 = new EqualTo(studentId, new Add(studentId, cid));
    List<Expression> expr = ImmutableList.of(eq1, eq2, eq3, or, less, eq4, eq5);
    LogicalJoin join = new LogicalJoin<>(JoinType.INNER_JOIN, new ArrayList<>(), expr, new DistributeHint(DistributeType.NONE), Optional.empty(), studentScan, scoreScan, null);
    PlanChecker.from(new ConnectContext(), join).applyTopDown(new FindHashConditionForJoin()).matches(logicalJoin().when(j -> j.getHashJoinConjuncts().equals(ImmutableList.of(eq1, eq3, eq4))).when(j -> j.getOtherJoinConjuncts().equals(ImmutableList.of(eq2, or, less, eq5))));
}

