     *                  |
     *                filter gender=1 and nameMax="abc" and (gender+10)<100
     *                  |
     *               aggregation group by gender
     *                  |
     *               scan(student)
     *
     *  transformed plan:
     *                project
     *                  |
     *                filter nameMax="abc"
     *                  |
     *               aggregation group by gender
     *                  |
     *               filter gender=1 and  and (gender+10)<100
     *                  |
     *               scan(student)
     */
@Test
public void pushDownPredicateTwoFilterTest() {
    Slot gender = scan.getOutput().get(1);
    NamedExpression nameMax = new Alias(new Max(scan.getOutput().get(2)), "nameMax");
    Expression filterPredicate = ExpressionUtils.and(new GreaterThan(gender, Literal.of(1)), new LessThanEqual(new Add(gender, Literal.of(10)), Literal.of(100)), new EqualTo(nameMax.toSlot(), Literal.of("abc")));
    LogicalPlan plan = new LogicalPlanBuilder(scan).aggGroupUsingIndex(ImmutableList.of(3, 1), ImmutableList.of(scan.getOutput().get(1), scan.getOutput().get(3), nameMax)).filter(filterPredicate).project(ImmutableList.of(0)).build();
    PlanChecker.from(MemoTestUtils.createConnectContext(), plan).applyTopDown(new PushDownFilterThroughAggregation()).printlnTree().matches(logicalProject(logicalFilter(logicalAggregate(logicalFilter(logicalOlapScan()).when(filter -> ImmutableList.copyOf(filter.getConjuncts()).get(0) instanceof GreaterThan && ImmutableList.copyOf(filter.getConjuncts()).get(1) instanceof LessThanEqual))).when(filter -> ImmutableList.copyOf(filter.getConjuncts()).get(0) instanceof EqualTo)));
}

