    plan = new LogicalPlanBuilder(repeatPlan).aggGroupUsingIndexAndSourceRepeat(ImmutableList.of(0, 1), ImmutableList.of(id, gender, nameMax), Optional.of(repeatPlan)).filter(filterPredicateId).project(ImmutableList.of(0)).build();
