@Test
public void testPushInsideInnerJoin() {
    Expression predicates = new Or(new And(// score.sid = student.id
    new EqualTo(scoreScan.getOutput().get(0), studentScan.getOutput().get(0)), // score.cid = course.cid
    new EqualTo(scoreScan.getOutput().get(1), courseScan.getOutput().get(0))), // grade > 2
    new GreaterThan(scoreScan.getOutput().get(2), new DoubleLiteral(2)));
    LogicalPlan plan = new LogicalPlanBuilder(scoreScan).joinEmptyOn(studentScan, JoinType.CROSS_JOIN).join(courseScan, JoinType.INNER_JOIN, // score.cid = course.cid
    ImmutableList.of(new EqualTo(scoreScan.getOutput().get(1), courseScan.getOutput().get(0))), // grade < 10
    ImmutableList.of(new LessThan(scoreScan.getOutput().get(2), new DoubleLiteral(10)))).filter(predicates).build();
    PlanChecker.from(MemoTestUtils.createConnectContext(), plan).applyTopDown(new PushFilterInsideJoin()).printlnTree().matchesFromRoot(logicalJoin().when(join -> join.getOtherJoinConjuncts().get(0).equals(predicates)));
}

