    parseExpression("'\\b'").assertEquals(new StringLiteral("\\b"));
    parseExpression("'\\n'").assertEquals(new StringLiteral("\\n"));
    parseExpression("'\\t'").assertEquals(new StringLiteral("\\t"));
    parseExpression("'\\0'").assertEquals(new StringLiteral("\\0"));
}

