@Test
public void testComplex() throws Exception {
    // array type
    checkCompareSameType(0, new ArrayLiteral(ImmutableList.of(new IntegerLiteral(100), new IntegerLiteral(200))), new ArrayLiteral(ImmutableList.of(new IntegerLiteral(100), new IntegerLiteral(200))));
    checkCompareSameType(1, new ArrayLiteral(ImmutableList.of(new IntegerLiteral(200))), new ArrayLiteral(ImmutableList.of(new IntegerLiteral(100), new IntegerLiteral(200))));
    checkCompareSameType(1, new ArrayLiteral(ImmutableList.of(new IntegerLiteral(100), new IntegerLiteral(200), new IntegerLiteral(1))), new ArrayLiteral(ImmutableList.of(new IntegerLiteral(100), new IntegerLiteral(200))));
    checkComparableNoException("select array(1,2) = array(1, 2)");
    checkComparableNoException("select array(1,2) > array(1, 2)");
    // json type
    checkNotComparable("select cast ('[1, 2]' as json) = cast('[1, 2]' as json)", "comparison predicate could not contains json type");
    checkNotComparable("select cast('[1, 2]' as json) > cast('[1, 2]' as json)", "comparison predicate could not contains json type");
    // map type
    checkNotComparable("select map(1, 2) = map(1, 2)", "comparison predicate could not contains complex type");
    checkNotComparable("select map(1, 2) > map(1, 2)", "comparison predicate could not contains complex type");
    checkNotComparable("select cast('(1, 2)' as map<int, int>) = cast('(1, 2)' as map<int, int>)", "comparison predicate could not contains complex type");
    // struct type
    checkNotComparable("select struct(1, 2) = struct(1, 2)", "comparison predicate could not contains complex type");
    checkNotComparable("select struct(1, 2) > struct(1, 2)", "comparison predicate could not contains complex type");
}

