    Expression whereClauseError = new EqualTo(error, new IntegerLiteral(2));
    ShowTabletsFromTableCommand command2 = new ShowTabletsFromTableCommand(tableNameInfo, partitionNamesInfo, whereClauseError, orderKeysNormal, 5, 0);
    Assertions.assertThrows(AnalysisException.class, () -> command2.validate(connectContext));
    // where clause contains or
    Expression backendId = new UnboundSlot("BackendId");
    Expression whereClauseOr = new Or(new EqualTo(version, new IntegerLiteral(2)), new EqualTo(backendId, new IntegerLiteral(2)));
    ShowTabletsFromTableCommand command3 = new ShowTabletsFromTableCommand(tableNameInfo, partitionNamesInfo, whereClauseOr, orderKeysNormal, 5, 0);
