@Test
public void testCreateTablePartitionForExternalCatalog() {
    PartitionDesc par = null;
    par = getCreateTableStmt("create table tb1 (id int not null, id2 int not null, id3 int not null)" + "partition by (id, id3) () distributed by hash (id) properties (\"a\"=\"b\")");
    Assertions.assertEquals("PARTITION BY LIST(`id`, `id3`)\n(\n\n)", par.toSql());
    try {
        getCreateTableStmt("create table tb1 (id int not null, id2 int not null, id3 int not null)" + "partition by (id, func1(id2, 1), func(3,id1), id3) () " + "distributed by hash (id) properties (\"a\"=\"b\")");
    } catch (Exception e) {
        Assertions.assertEquals("errCode = 2, detailMessage = auto create partition only support slotRef in list partitions. func1(`id2`, '1')", e.getMessage());
    }
    try {
        getCreateTableStmt("create table tb1 (id int not null, id2 int not null, id3 int not null) " + "ENGINE=iceberg partition by (id, func1(id2, 1), func(3,id1), id3) () " + "distributed by hash (id) properties (\"a\"=\"b\")");
    } catch (Exception e) {
        Assertions.assertEquals("Iceberg doesn't support 'DISTRIBUTE BY', " + "and you can use 'bucket(num, column)' in 'PARTITIONED BY'.", e.getMessage());
    }
    par = getCreateTableStmt("create table tb1 (id int not null, id2 int not null, id3 int not null) " + "ENGINE=iceberg partition by (id, func1(id2, 1), func(3,id1), id3) () properties (\"a\"=\"b\")");
    Assertions.assertEquals("PARTITION BY LIST(`id`, func1(`id2`, '1'), func('3', `id1`), `id3`)\n" + "(\n" + "\n" + ")", par.toSql());
    try {
        getCreateTableStmt("create table tb1 (id int) " + "engine = iceberg rollup (ab (cd)) properties (\"a\"=\"b\")");
    } catch (Exception e) {
        Assertions.assertEquals("iceberg catalog doesn't support rollup tables.", e.getMessage());
    }
    try {
        getCreateTableStmt("create table tb1 (id int) engine = hive rollup (ab (cd)) properties (\"a\"=\"b\")");
    } catch (Exception e) {
        Assertions.assertEquals("hive catalog doesn't support rollup tables.", e.getMessage());
    }
    // test with empty partitions
    LogicalPlan plan = new NereidsParser().parseSingle("create table tb1 (id int) engine = iceberg properties (\"a\"=\"b\")");
    Assertions.assertTrue(plan instanceof CreateTableCommand);
    CreateTableInfo createTableInfo = ((CreateTableCommand) plan).getCreateTableInfo();
    createTableInfo.validate(connectContext);
    Assertions.assertNull(createTableInfo.translateToLegacyStmt().getPartitionDesc());
    // test with multi partitions
    LogicalPlan plan2 = new NereidsParser().parseSingle("create table tb1 (id int) engine = iceberg " + "partition by (val, bucket(2, id), par, day(ts), efg(a,b,c)) () properties (\"a\"=\"b\")");
    Assertions.assertTrue(plan2 instanceof CreateTableCommand);
    CreateTableInfo createTableInfo2 = ((CreateTableCommand) plan2).getCreateTableInfo();
    createTableInfo2.validate(connectContext);
    PartitionDesc partitionDesc2 = createTableInfo2.translateToLegacyStmt().getPartitionDesc();
    List<Expr> partitionFields2 = partitionDesc2.getPartitionExprs();
    Assertions.assertEquals(5, partitionFields2.size());
    Expr expr0 = partitionFields2.get(0);
    Assertions.assertInstanceOf(SlotRef.class, expr0);
    Assertions.assertEquals("val", expr0.getExprName());
    Expr expr1 = partitionFields2.get(1);
    Assertions.assertInstanceOf(FunctionCallExpr.class, expr1);
    List<Expr> params1 = ((FunctionCallExpr) expr1).getParams().exprs();
    Assertions.assertEquals("bucket", expr1.getExprName());
    Assertions.assertEquals(2, params1.size());
    Assertions.assertInstanceOf(StringLiteral.class, params1.get(0));
    Assertions.assertEquals("2", params1.get(0).getStringValue());
    Assertions.assertInstanceOf(SlotRef.class, params1.get(1));
    Assertions.assertEquals("id", params1.get(1).getExprName());
    Expr expr2 = partitionFields2.get(2);
    Assertions.assertInstanceOf(SlotRef.class, expr2);
    Assertions.assertEquals("par", expr2.getExprName());
    Expr expr3 = partitionFields2.get(3);
    Assertions.assertInstanceOf(FunctionCallExpr.class, expr3);
    List<Expr> params3 = ((FunctionCallExpr) expr3).getParams().exprs();
    Assertions.assertEquals("day", expr3.getExprName());
    Assertions.assertEquals(1, params3.size());
    Assertions.assertInstanceOf(SlotRef.class, params3.get(0));
    Assertions.assertEquals("ts", params3.get(0).getExprName());
    Expr expr4 = partitionFields2.get(4);
    Assertions.assertInstanceOf(FunctionCallExpr.class, expr4);
    List<Expr> params4 = ((FunctionCallExpr) expr4).getParams().exprs();
    Assertions.assertEquals("efg", expr4.getExprName());
    Assertions.assertEquals(3, params4.size());
    Assertions.assertInstanceOf(SlotRef.class, params4.get(0));
    Assertions.assertEquals("a", params4.get(0).getExprName());
    Assertions.assertInstanceOf(SlotRef.class, params4.get(1));
    Assertions.assertEquals("b", params4.get(1).getExprName());
    Assertions.assertInstanceOf(SlotRef.class, params4.get(2));
    Assertions.assertEquals("c", params4.get(2).getExprName());
    Assertions.assertEquals("PARTITION BY LIST(`val`, bucket('2', `id`), `par`, day(`ts`), efg(`a`, `b`, `c`))\n(\n\n)", partitionDesc2.toSql());
}

@Test
public void testPartitionCheckForHive() {
    try {
        getCreateTableStmt("CREATE TABLE `tb11`(\n" + "    `par1` int\n" + ") ENGINE = hive PARTITION BY LIST (\n" + "    par1\n" + ")();");
        Assertions.assertTrue(false);
    } catch (Exception e) {
        Assertions.assertEquals("Cannot set all columns as partitioning columns.", e.getMessage());
    }
    try {
        getCreateTableStmt("CREATE TABLE `tb11`(\n" + "    `par1` int,\n" + "    `c1` bigint\n" + ") ENGINE = hive PARTITION BY LIST (\n" + "    par1\n" + ")();");
        Assertions.assertTrue(false);
    } catch (Exception e) {
        Assertions.assertEquals("The partition field must be at the end of the schema.", e.getMessage());
    }
    try {
        getCreateTableStmt("CREATE TABLE `tb11`(\n" + "    `c1` bigint,\n" + "    `par2` int,\n" + "    `par1` int\n" + ") ENGINE = hive PARTITION BY LIST (\n" + "    par1, par2\n" + ")();");
        Assertions.assertTrue(false);
    } catch (Exception e) {
        Assertions.assertEquals("The order of partition fields in the schema " + "must be consistent with the order defined in `PARTITIONED BY LIST()`", e.getMessage());
    }
    try {
        getCreateTableStmt("CREATE TABLE `tb11`(\n" + "    `c1` bigint,\n" + "    `par2` int\n" + ") ENGINE = hive PARTITION BY LIST (\n" + "    par1, par2, par3 ,par4\n" + ")();");
        Assertions.assertTrue(false);
    } catch (Exception e) {
        Assertions.assertEquals("partition key par1 is not exists", e.getMessage());
    }
    try {
        getCreateTableStmt("CREATE TABLE `tb11`(\n" + "    `c1` bigint,\n" + "    `par1` int,\n" + "    `par2` int,\n" + "    `par3` int\n" + ") ENGINE = hive PARTITION BY LIST (\n" + "    par1, par2\n" + ")();");
        Assertions.assertTrue(false);
    } catch (Exception e) {
        Assertions.assertEquals("The partition field must be at the end of the schema.", e.getMessage());
    }
}

@Test
public void testFromClauseDelete() throws AnalysisException {
    String sql = "delete from t1 a using src join t2 on src.k1 = t2.k1 where t2.k1 = a.k1";
    LogicalPlan parsed = new NereidsParser().parseSingle(sql);
    Assertions.assertInstanceOf(DeleteFromUsingCommand.class, parsed);
    DeleteFromUsingCommand command = ((DeleteFromUsingCommand) parsed);
    LogicalPlan plan = command.completeQueryPlan(connectContext, command.getLogicalQuery());
    PlanChecker.from(connectContext, plan).analyze(plan).rewrite().matches(logicalOlapTableSink(logicalProject(logicalJoin(logicalProject(logicalJoin(logicalProject(logicalFilter(logicalOlapScan())), logicalProject(logicalFilter(logicalOlapScan())))), logicalProject(logicalOlapScan())))));
}

