@Test
public void test() {
    SlotReference slot = new SlotReference("slot", BooleanType.INSTANCE);
    MarkJoinSlotReference markSlot1 = new MarkJoinSlotReference("markSlot1");
    MarkJoinSlotReference markSlot2 = new MarkJoinSlotReference("markSlot2");
    MarkJoinSlotReference markSlot3 = new MarkJoinSlotReference("markSlot1");
    MarkJoinSlotReference markSlot4 = new MarkJoinSlotReference("markSlot2");
    MarkJoinSlotReference markSlot5 = new MarkJoinSlotReference("markSlot1");
    List<Expression> markJoinSlotReferenceList1 = Lists.newArrayList(markSlot1, markSlot2, markSlot3, markSlot4);
    List<Expression> markJoinSlotReferenceList2 = Lists.newArrayList(markSlot1, markSlot2, markSlot3, markSlot4, markSlot5);
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new And(BooleanLiteral.TRUE, markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new And(BooleanLiteral.FALSE, markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new And(NullLiteral.INSTANCE, markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new Or(BooleanLiteral.TRUE, markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new Or(BooleanLiteral.FALSE, markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new Or(NullLiteral.INSTANCE, markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new And(new Or(BooleanLiteral.TRUE, markSlot2), markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new And(new Or(BooleanLiteral.FALSE, markSlot2), markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new And(new Or(NullLiteral.INSTANCE, markSlot2), markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new Or(new And(BooleanLiteral.TRUE, markSlot2), markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new Or(new And(BooleanLiteral.FALSE, markSlot2), markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new Or(new And(NullLiteral.INSTANCE, markSlot2), markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new And(new Or(BooleanLiteral.FALSE, markSlot2), new IsNull(markSlot1)), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new And(new Or(NullLiteral.INSTANCE, markSlot2), new IsNull(markSlot1)), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new And(new IsNull(markSlot2), markSlot1), context));
    Assertions.assertTrue(ExpressionUtils.canInferNotNullForMarkSlot(new Or(markJoinSlotReferenceList1), context));
    Assertions.assertFalse(ExpressionUtils.canInferNotNullForMarkSlot(new Or(new IsNull(markSlot2), markSlot1), context));
    Assertions.assertFalse(ExpressionUtils.canInferNotNullForMarkSlot(new And(new Or(BooleanLiteral.TRUE, markSlot2), new IsNull(markSlot1)), context));
    Assertions.assertFalse(ExpressionUtils.canInferNotNullForMarkSlot(new Or(new And(BooleanLiteral.TRUE, markSlot2), new IsNull(markSlot1)), context));
    Assertions.assertFalse(ExpressionUtils.canInferNotNullForMarkSlot(new Or(new And(BooleanLiteral.FALSE, markSlot2), new IsNull(markSlot1)), context));
    Assertions.assertFalse(ExpressionUtils.canInferNotNullForMarkSlot(new Or(new And(NullLiteral.INSTANCE, markSlot2), new IsNull(markSlot1)), context));
    Assertions.assertFalse(ExpressionUtils.canInferNotNullForMarkSlot(new And(slot, markSlot1), context));
    Assertions.assertFalse(ExpressionUtils.canInferNotNullForMarkSlot(new Or(markJoinSlotReferenceList2), context));
}

