    Assertions.assertEquals(new CharLiteral("char", 4), TypeCoercionUtils.castIfNotSameType(new CharLiteral("char", 4), VarcharType.createVarcharType(100)));
    Assertions.assertEquals(new StringLiteral("string"), TypeCoercionUtils.castIfNotSameType(new StringLiteral("string"), VarcharType.createVarcharType(100)));
}

@Test
public void testDecimalArithmetic() {
    Multiply multiply = new Multiply(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    Expression expression = TypeCoercionUtils.processBinaryArithmetic(multiply);
    Assertions.assertEquals(expression.child(0), new Cast(multiply.child(0), DecimalV3Type.createDecimalV3Type(9, 3)));
    Divide divide = new Divide(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    expression = TypeCoercionUtils.processBinaryArithmetic(divide);
    Assertions.assertEquals(expression.child(0), new Cast(multiply.child(0), DecimalV3Type.createDecimalV3Type(9, 3)));
    Add add = new Add(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    expression = TypeCoercionUtils.processBinaryArithmetic(add);
    Assertions.assertEquals(expression.child(0), new Cast(multiply.child(0), DecimalV3Type.createDecimalV3Type(10, 3)));
    Subtract sub = new Subtract(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    expression = TypeCoercionUtils.processBinaryArithmetic(sub);
    Assertions.assertEquals(expression.child(0), new Cast(multiply.child(0), DecimalV3Type.createDecimalV3Type(10, 3)));
}

@Test
public void testProcessInDowngrade() {
    // DecimalV2 slot vs DecimalV3 literal
    InPredicate decimalDowngrade = new InPredicate(new SlotReference("c1", DecimalV2Type.createDecimalV2Type(15, 6)), ImmutableList.of(new DecimalV3Literal(BigDecimal.valueOf(12345.1234567)), new DecimalLiteral(BigDecimal.valueOf(12345.1234))));
    decimalDowngrade = (InPredicate) TypeCoercionUtils.processInPredicate(decimalDowngrade);
    Assertions.assertEquals(DecimalV2Type.createDecimalV2Type(16, 7), decimalDowngrade.getCompareExpr().getDataType());
    // DateV1 slot vs DateV2 literal
    InPredicate dateDowngrade = new InPredicate(new SlotReference("c1", DateType.INSTANCE), ImmutableList.of(new DateLiteral(2024, 4, 12), new DateV2Literal(2024, 4, 12)));
    dateDowngrade = (InPredicate) TypeCoercionUtils.processInPredicate(dateDowngrade);
    Assertions.assertEquals(DateType.INSTANCE, dateDowngrade.getCompareExpr().getDataType());
    // DatetimeV1 slot vs DateLike literal
    InPredicate datetimeDowngrade = new InPredicate(new SlotReference("c1", DateTimeType.INSTANCE), ImmutableList.of(new DateLiteral(2024, 4, 12), new DateV2Literal(2024, 4, 12), new DateTimeLiteral(2024, 4, 12, 18, 25, 30), new DateTimeV2Literal(2024, 4, 12, 18, 25, 30, 0)));
    datetimeDowngrade = (InPredicate) TypeCoercionUtils.processInPredicate(datetimeDowngrade);
    Assertions.assertEquals(DateTimeType.INSTANCE, datetimeDowngrade.getCompareExpr().getDataType());
}

@Test
public void testProcessComparisonPredicateDowngrade() {
    // DecimalV2 slot vs DecimalV3 literal
    EqualTo decimalDowngrade = new EqualTo(new SlotReference("c1", DecimalV2Type.createDecimalV2Type(15, 6)), new DecimalV3Literal(BigDecimal.valueOf(12345.1234567)));
    decimalDowngrade = (EqualTo) TypeCoercionUtils.processComparisonPredicate(decimalDowngrade);
    Assertions.assertEquals(DecimalV2Type.createDecimalV2Type(16, 7), decimalDowngrade.left().getDataType());
    // DateV1 slot vs DateV2 literal (this case cover right slot vs left literal)
    EqualTo dateDowngrade = new EqualTo(new DateV2Literal(2024, 4, 12), new SlotReference("c1", DateType.INSTANCE));
    dateDowngrade = (EqualTo) TypeCoercionUtils.processComparisonPredicate(dateDowngrade);
    Assertions.assertEquals(DateType.INSTANCE, dateDowngrade.left().getDataType());
    // DatetimeV1 slot vs DateLike literal
    EqualTo datetimeDowngrade = new EqualTo(new SlotReference("c1", DateTimeType.INSTANCE), new DateTimeV2Literal(2024, 4, 12, 18, 25, 30, 0));
    datetimeDowngrade = (EqualTo) TypeCoercionUtils.processComparisonPredicate(datetimeDowngrade);
    Assertions.assertEquals(DateTimeType.INSTANCE, datetimeDowngrade.left().getDataType());
}

@Test
public void testProcessInStringCoercion() {
    // BigInt slot vs String literal
    InPredicate bigintString = new InPredicate(new SlotReference("c1", BigIntType.INSTANCE), ImmutableList.of(new VarcharLiteral("200"), new VarcharLiteral("922337203685477001")));
    bigintString = (InPredicate) TypeCoercionUtils.processInPredicate(bigintString);
    Assertions.assertEquals(BigIntType.INSTANCE, bigintString.getCompareExpr().getDataType());
    Assertions.assertEquals(BigIntType.INSTANCE, bigintString.getOptions().get(0).getDataType());
    // SmallInt slot vs String literal
    InPredicate smallIntString = new InPredicate(new SlotReference("c1", SmallIntType.INSTANCE), ImmutableList.of(new DecimalLiteral(new BigDecimal("987654.321")), new VarcharLiteral("922337203685477001")));
    smallIntString = (InPredicate) TypeCoercionUtils.processInPredicate(smallIntString);
    Assertions.assertEquals(DecimalV3Type.createDecimalV3Type(23, 3), smallIntString.getCompareExpr().getDataType());
    Assertions.assertEquals(DecimalV3Type.createDecimalV3Type(23, 3), smallIntString.getOptions().get(0).getDataType());
}

