    List<TNormalizedPlanNode> onePhaseAggPlans = onePhaseAggWithDistinct(() -> normalizePlans("select distinct k1 from db1.part1 where dt = '2024-04-10'"));
    Assertions.assertEquals(noDistinctPlans, onePhaseAggPlans);
    List<TNormalizedPlanNode> twoPhaseAggPlans = twoPhaseAggWithDistinct(() -> normalizePlans("select distinct k1 from db1.part1 where dt = '2024-04-10'"));
    Assertions.assertEquals(onePhaseAggPlans, twoPhaseAggPlans);
    List<TNormalizedPlanNode> threePhaseAggPlans = threePhaseAggWithDistinct(() -> normalizePlans("select sum(distinct v1), k1 from db1.part1 where dt = '2024-04-10' group by k1"));
    List<TNormalizedPlanNode> fourPhaseAggPlans = fourPhaseAggWithDistinct(() -> normalizePlans("select sum(distinct v1), k1 from db1.part1 where dt = '2024-04-10' group by k1"));
    Assertions.assertNotEquals(fourPhaseAggPlans, threePhaseAggPlans);
}

