@Test
public void testIsBucketShuffleJoin() {
    PlanFragmentId planFragmentId = new PlanFragmentId(1);
    int scanNodeId = 1;
    // The "fragmentIdToScanNodeIds" we created here is useless in this test.
    // It is only for creating the BucketShuffleJoinController.
    // So the fragment id and scan node id in it is meaningless.
    Map<PlanFragmentId, Set<Integer>> fragmentIdToScanNodeIds = new HashMap<>();
    fragmentIdToScanNodeIds.put(planFragmentId, new HashSet<>());
    fragmentIdToScanNodeIds.get(planFragmentId).add(scanNodeId);
    Coordinator.BucketShuffleJoinController bucketShuffleJoinController = new Coordinator.BucketShuffleJoinController(fragmentIdToScanNodeIds);
    PlanNodeId testPlanNodeId = new PlanNodeId(-1);
    TupleId testTupleId = new TupleId(-1);
    ArrayList<TupleId> tupleIdArrayList = new ArrayList<>();
    tupleIdArrayList.add(testTupleId);
    ArrayList<Expr> testJoinexprs = new ArrayList<>();
    BinaryPredicate binaryPredicate = new BinaryPredicate(BinaryPredicate.Operator.EQ, new BoolLiteral(true), new BoolLiteral(true));
    testJoinexprs.add(binaryPredicate);
    HashJoinNode hashJoinNode = new HashJoinNode(testPlanNodeId, new EmptySetNode(testPlanNodeId, tupleIdArrayList), new EmptySetNode(testPlanNodeId, tupleIdArrayList), new TableRef(), testJoinexprs, new ArrayList<>());
    hashJoinNode.setFragment(new PlanFragment(new PlanFragmentId(-1), hashJoinNode, new DataPartition(TPartitionType.BUCKET_SHFFULE_HASH_PARTITIONED, testJoinexprs)));
    // hash join node is not bucket shuffle join
    Assert.assertEquals(false, Deencapsulation.invoke(bucketShuffleJoinController, "isBucketShuffleJoin", -1, hashJoinNode));
    // the fragment id is different from hash join node
    hashJoinNode.setFragment(new PlanFragment(new PlanFragmentId(-2), hashJoinNode, new DataPartition(TPartitionType.BUCKET_SHFFULE_HASH_PARTITIONED, testJoinexprs)));
    hashJoinNode.setDistributionMode(HashJoinNode.DistributionMode.BUCKET_SHUFFLE);
    Assert.assertEquals(false, Deencapsulation.invoke(bucketShuffleJoinController, "isBucketShuffleJoin", -1, hashJoinNode));
    hashJoinNode.setFragment(new PlanFragment(new PlanFragmentId(-1), hashJoinNode, new DataPartition(TPartitionType.BUCKET_SHFFULE_HASH_PARTITIONED, testJoinexprs)));
    Assert.assertEquals(true, Deencapsulation.invoke(bucketShuffleJoinController, "isBucketShuffleJoin", -1, hashJoinNode));
    // the fragment id is in cache, so not do check node again
    Assert.assertEquals(true, Deencapsulation.invoke(bucketShuffleJoinController, "isBucketShuffleJoin", -1));
}

