    Set<Tag> emptyTagSet = Sets.newHashSet();
    Assert.assertTrue(cgmgr.getComputeGroup(emptyTagSet).getBackendList().size() == 0);
    Assert.assertTrue(cgmgr.getAllBackendComputeGroup().getBackendList().size() == 5);
}

